import React from 'react';
import { Child } from '../types';

interface NestCardProps {
  child: Child;
  onClick?: () => void;
  selected?: boolean;
}

/**
 * NestCard
 * 
 * The signature visual motif of NestFlow.
 * Features an asymmetrical "Nest" shape holding the avatar.
 * Uses springy hover effects.
 */
export const NestCard: React.FC<NestCardProps> = ({ child, onClick, selected }) => {
  return (
    <div 
      onClick={onClick}
      className={`
        relative group cursor-pointer 
        transition-all duration-300 ease-out 
        hover:-translate-y-1 hover:shadow-lg
        ${selected ? 'ring-4 ring-primary-300 ring-opacity-50' : ''}
      `}
    >
      {/* Main Card Body */}
      <div className="bg-white rounded-nest overflow-hidden shadow-sm border border-gray-100 h-28 flex">

        {/* The "Nest" Blob Container - Asymmetrical Left Side */}
        <div className="w-24 h-full relative overflow-hidden bg-primary-100">
          {/* Decorative Blob Shape Background */}
          <div className="absolute -top-4 -left-4 w-32 h-32 bg-primary-300 rounded-full opacity-20 transform rotate-12"></div>

          <div className="absolute inset-0 flex items-center justify-center">
             <img 
               src={child.avatarUrl} 
               alt={child.firstName}
               className="w-16 h-16 rounded-full object-cover border-4 border-white shadow-sm"
             />
          </div>
        </div>

        {/* Content Side */}
        <div className="flex-1 p-3 flex flex-col justify-center">
          <div className="flex justify-between items-start">
            <h3 className="font-display font-bold text-gray-800 text-lg">
              {child.firstName}
            </h3>
            <span className={`
              text-[10px] font-bold px-2 py-1 rounded-full uppercase tracking-wider
              ${child.status === 'PRESENT' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}
            `}>
              {child.status === 'PRESENT' ? 'Here' : 'Away'}
            </span>
          </div>

          <p className="text-sm text-gray-500 mb-2">{child.lastName}</p>

          {child.lastActivityTime && (
            <div className="flex items-center text-xs text-gray-400">
              <span className="w-2 h-2 bg-accent-300 rounded-full mr-2 animate-pulse"></span>
              {child.lastActivityTime}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Activity, ActivityType } from '../types';

interface ActivityFeedItemProps {
  activity: Activity;
}

export const ActivityFeedItem: React.FC<ActivityFeedItemProps> = ({ activity }) => {

  const getIcon = (type: ActivityType) => {
    switch (type) {
      case ActivityType.PHOTO: return '📸';
      case ActivityType.MEAL: return '🍎';
      case ActivityType.NAP: return '😴';
      case ActivityType.CHECK_IN: return '👋';
      default: return '📝';
    }
  };

  return (
    <div className="flex gap-4 mb-6 relative">
      {/* Timeline Connector */}
      <div className="absolute left-[19px] top-10 bottom-[-24px] w-0.5 bg-gray-200 -z-10" />

      {/* Icon Bubble */}
      <div className="w-10 h-10 rounded-full bg-white border-2 border-primary-100 flex items-center justify-center text-xl shadow-sm shrink-0 z-0">
        {getIcon(activity.type)}
      </div>

      {/* Card Content */}
      <div className="flex-1 bg-white rounded-2xl p-4 shadow-sm border border-gray-100">
        <div className="flex justify-between items-start mb-2">
          <h4 className="font-display font-bold text-gray-800">{activity.title}</h4>
          <span className="text-xs text-gray-400">{activity.timestamp}</span>
        </div>

        {activity.description && (
          <p className="text-gray-600 text-sm mb-3 leading-relaxed">
            {activity.description}
          </p>
        )}

        {activity.mediaUrl && (
          <div className="rounded-xl overflow-hidden mt-2 mb-2">
            <img 
              src={activity.mediaUrl} 
              alt="Activity" 
              className="w-full h-48 object-cover hover:scale-105 transition-transform duration-500"
            />
          </div>
        )}

        <div className="flex items-center justify-between mt-2 pt-2 border-t border-gray-50">
          <span className="text-xs text-gray-400 font-medium">By {activity.authorName}</span>
          <button className="text-accent-300 hover:text-accent-400 text-sm font-semibold transition-colors">
            Like
          </button>
        </div>
      </div>
    </div>
  );
};

