const App: React.FC = () => {
  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('toddlers');
  const [selectedChildId, setSelectedChildId] = useState<string | null>('1');
