                    : 'text-gray-600 hover:bg-gray-50 font-medium border border-transparent'}
                `}
              >
                <span>{room.name}</span>
                <span className={`
                  text-[10px] px-1.5 py-0.5 rounded font-bold
                  ${isActive ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}
                `}>
                  {room.enrolled}/{room.capacity}
                </span>
              </div>
            );
          })}
        </div>
      </div>

      {/* Control Center Widget Mini */}
      <div className="mt-8 p-4 bg-gray-50 rounded-xl border border-gray-100">
        <h4 className="text-xs font-bold text-gray-500 mb-2">Center Health</h4>
        <div className="flex justify-between items-end">
          <div>
            <div className="text-2xl font-display font-bold text-gray-800">94%</div>
            <div className="text-[10px] text-gray-400">Attendance</div>
          </div>
          <div className="h-8 w-8 rounded-full bg-green-100 flex items-center justify-center text-green-600 text-xs">
            ▲
          </div>
        </div>
      </div>
    </div>
  );

  const ListPanelContent = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-4">
        <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">
