        return invoices.reduce((acc, inv) => {
            if (inv.status === 'PENDING' || inv.status === 'OVERDUE') {
                const amount = parseFloat(inv.amount.replace(/[^0-9.-]+/g,""));
                return acc + amount;
            }
            return acc;
        }, 0);
