                    {/* Content */}
                    <div className="p-8 overflow-y-auto bg-gray-50/50 flex-1 space-y-8">

                        {/* 1. Attendance Overview */}
                        <section>
                            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4">Daily Attendance</h3>
