                                </button>
                                <button className="w-8 h-8 rounded-full bg-accent-300 text-white flex items-center justify-center hover:bg-accent-400">
                                    ✉️
                                </button>
                            </div>
                        </div>
                    )) : (
                        <div className="text-center text-gray-400 py-8">No guardian info available.</div>
