                                        <p className="text-gray-400 mb-1">Date of Birth</p>
                                        <p className="font-medium text-gray-700">{selectedChild.dob || 'N/A'}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-400 mb-1">Age</p>
                                        <p className="font-medium text-gray-700">3 Years</p>
                                    </div>
