          <div className="text-gray-600 px-3 py-2 rounded-lg font-medium text-sm hover:bg-gray-50 cursor-pointer transition-colors">
            North Hills Campus
          </div>
        </div>
      </div>
      <div>
        <div className="flex justify-between items-center mb-3 pl-2 pr-2">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Classrooms</h3>
