                                                                className={`h-full rounded-full ${room.utilization > 90 ? 'bg-red-400' : 'bg-primary-400'}`} 
                                                                style={{ width: `${room.utilization}%` }}
                                                            ></div>
                                                        </div>
                                                        <span className="text-xs font-bold text-gray-500">{room.utilization}%</span>
                                                    </div>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </section>
                    </div>
                </div>
            </div>
        )}
    </>
  );
};

