                                <div className="grid grid-cols-2 gap-3">
                                    <div>
                                        <label className="text-[10px] font-bold text-gray-400 uppercase">Phone</label>
                                        <input 
                                            type="tel"
                                            value={newGuardianData.phone || ''}
                                            onChange={e => setNewGuardianData(prev => ({...prev, phone: e.target.value}))}
