    e.preventDefault();
    setIsLoading(true);

    if (isSignUp) {
        // Sign Up Simulation
        if (password !== confirmPassword) {
            alert("Passwords do not match!");
            setIsLoading(false);
            return;
        }

        setTimeout(() => {
            setIsLoading(false);
            setSignUpSuccess(true);
            // In a real app, this is where backend would trigger email
        }, 1500);
    } else {
        // Login Simulation
        setTimeout(() => {
            setIsLoading(false);
            onLogin();
        }, 1000);
    }
  };

  const handleSwitchMode = () => {
      setIsSignUp(!isSignUp);
      setSignUpSuccess(false);
      setEmail('');
      setPassword('');
      setConfirmPassword('');
      setFullName('');
