const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Toast Notification State
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // App Section State
  const [activeSection, setActiveSection] = useState<AppSection>('DAILY_OPS');

  // Navigation History
  const [navHistory, setNavHistory] = useState<AppSection[]>(['DAILY_OPS']);

  // Center State
  const [selectedCenterId, setSelectedCenterId] = useState<string>('c1');

  // Data State
  const [classrooms, setClassrooms] = useState<Classroom[]>(INITIAL_CLASSROOMS);
  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [activities, setActivities] = useState<Activity[]>(MOCK_ACTIVITIES);
  const [guardiansMap, setGuardiansMap] = useState<Record<string, Guardian[]>>(INITIAL_GUARDIANS);
  const [invoicesMap, setInvoicesMap] = useState<Record<string, Invoice[]>>(INITIAL_INVOICES);

  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('toddlers');
  const [selectedChildId, setSelectedChildId] = useState<string | null>('1');
  const [activeDetailTab, setActiveDetailTab] = useState<DetailTab>('TIMELINE');

  // Enrollment State
  const [enrollmentTab, setEnrollmentTab] = useState<'PENDING' | 'WAITLIST'>('PENDING');

  // Add Classroom State
  const [isAddingClassroom, setIsAddingClassroom] = useState(false);
  const [newClassroomName, setNewClassroomName] = useState('');

  // Edit Mode State (Full Profile)
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editFormData, setEditFormData] = useState<Partial<Child>>({});

  // Inline Notes Edit State
  const [isEditingNotes, setIsEditingNotes] = useState(false);
  const [notesBuffer, setNotesBuffer] = useState('');

  // Add Guardian State
  const [isAddingGuardian, setIsAddingGuardian] = useState(false);
  const [newGuardianData, setNewGuardianData] = useState<Partial<Guardian>>({});

  // Payment Processing State
  const [processingInvoiceId, setProcessingInvoiceId] = useState<string | null>(null);

  // Health Analytics Modal State
  const [isHealthAnalyticsOpen, setIsHealthAnalyticsOpen] = useState(false);

  // Derived State
  const filteredChildren = activeSection === 'DAILY_OPS' 
    ? children.filter(c => c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED')
    : children.filter(c => c.enrollmentStatus === enrollmentTab);

  const selectedChild = children.find(c => c.id === selectedChildId);
  const currentClassroom = classrooms.find(c => c.id === selectedClassroomId);

  // Helper function to parse money string to number
  const parseMoney = (str: string) => parseFloat(str.replace(/[^0-9.-]+/g,""));

  // Calculate Real-time Metrics
  const calculateMetrics = () => {
      const totalChildren = children.filter(c => c.enrollmentStatus === 'ENROLLED').length;
      const present = children.filter(c => c.status === 'PRESENT' && c.enrollmentStatus === 'ENROLLED').length;
      const absent = children.filter(c => c.status === 'ABSENT' && c.enrollmentStatus === 'ENROLLED').length;
      const checkedOut = children.filter(c => c.status === 'CHECKED_OUT' && c.enrollmentStatus === 'ENROLLED').length;

      const totalCapacity = classrooms.reduce((acc, room) => acc + room.capacity, 0);

      // Billing Calculation
      const allInvoices = Object.values(invoicesMap).flat() as Invoice[];
      const totalRevenue = allInvoices
          .filter(i => i.status === 'PAID')
          .reduce((acc, i) => acc + parseMoney(i.amount), 0);
      const pendingRevenue = allInvoices
          .filter(i => i.status === 'PENDING')
          .reduce((acc, i) => acc + parseMoney(i.amount), 0);
      const overdueRevenue = allInvoices
          .filter(i => i.status === 'OVERDUE')
          .reduce((acc, i) => acc + parseMoney(i.amount), 0);

      return {
          attendance: { 
              total: totalChildren, 
              present, 
              absent, 
              checkedOut, 
              rate: totalChildren ? Math.round((present / totalChildren) * 100) : 0 
          },
          capacity: { 
              total: totalCapacity, 
              enrolled: totalChildren, 
              utilization: totalCapacity ? Math.round((totalChildren / totalCapacity) * 100) : 0 
          },
          billing: { 
              totalRevenue, 
              pendingRevenue, 
              overdueRevenue 
          },
          classrooms: classrooms.map(room => {
               const roomChildren = children.filter(c => c.classroomId === room.id && c.enrollmentStatus === 'ENROLLED');
               const roomPresent = roomChildren.filter(c => c.status === 'PRESENT').length;
               return { 
                   ...room, 
                   actualEnrolled: roomChildren.length, 
                   presentCount: roomPresent,
                   utilization: Math.round((roomChildren.length / room.capacity) * 100)
               };
          })
      };
  }

  const metrics = calculateMetrics();

  // Effects
  useEffect(() => {
    // Reset editing states when switching children
    setIsEditingProfile(false);
    setIsEditingNotes(false);
    setIsAddingGuardian(false);
    setNewGuardianData({});
    setProcessingInvoiceId(null);
  }, [selectedChildId]);

  useEffect(() => {
      // Reset selection when switching sections
      setSelectedChildId(null);
  }, [activeSection, enrollmentTab]);

  // --- Handlers ---

  const navigateTo = (section: AppSection) => {
    if (section === activeSection) return;
    setNavHistory(prev => [...prev, section]);
    setActiveSection(section);
    setSelectedChildId(null); // Clear selection when changing main section
  };

  const goBack = () => {
    if (navHistory.length > 1) {
        const newHistory = [...navHistory];
        newHistory.pop(); // Remove current
        const prevSection = newHistory[newHistory.length - 1];
        setNavHistory(newHistory);
        setActiveSection(prevSection);
        setSelectedChildId(null);
    }
  };

  const goHome = () => {
    setNavHistory(['DAILY_OPS']);
    setActiveSection('DAILY_OPS');
    setSelectedChildId(null);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
  };

  const handleEnrollChild = (childId: string, classroomId: string) => {
      const room = classrooms.find(r => r.id === classroomId);
      if (!room) return;

      setChildren(prev => prev.map(c => 
          c.id === childId 
            ? { ...c, enrollmentStatus: 'ENROLLED', classroomId: classroomId, classroom: room.name } 
            : c
      ));

      setToast({ message: `Successfully enrolled child in ${room.name}`, type: 'success' });
      setTimeout(() => setToast(null), 3000);
      setSelectedChildId(null);
  };

  const handleMoveToWaitlist = (childId: string) => {
      setChildren(prev => prev.map(c => 
          c.id === childId ? { ...c, enrollmentStatus: 'WAITLIST' } : c
