        )}

        {/* --- TOAST NOTIFICATION --- */}
        {toast && (
            <div className={`fixed bottom-6 right-6 px-6 py-4 rounded-xl shadow-xl flex items-center gap-3 animate-in slide-in-from-bottom-4 fade-in duration-300 z-50 ${
