                                    <div key={imm.id} className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                                        <div className="flex justify-between mb-2">
                                            <span className="font-bold text-sm text-gray-700">{imm.name}</span>
                                            <span className="text-xs text-gray-400">Due: {imm.dueDate}</span>
                                        </div>
                                        <div className="grid grid-cols-2 gap-2">
                                            <div>
                                                <label className="text-[10px] font-bold text-gray-400 uppercase">Status</label>
                                                <select
                                                    value={imm.status}
                                                    onChange={(e) => {
                                                        const newForm = [...immunizationForm];
                                                        newForm[idx] = { ...newForm[idx], status: e.target.value as any };
                                                        setImmunizationForm(newForm);
                                                    }}
                                                    className="w-full text-xs p-1.5 rounded border border-gray-200"
                                                >
                                                    <option value="COMPLIANT">Compliant</option>
                                                    <option value="OVERDUE">Overdue</option>
                                                    <option value="UPCOMING">Upcoming</option>
                                                </select>
                                            </div>
                                            <div>
                                                <label className="text-[10px] font-bold text-gray-400 uppercase">Date Given</label>
                                                <input
                                                    type="date"
                                                    value={imm.dateGiven || ''}
                                                    onChange={(e) => {
                                                        const newForm = [...immunizationForm];
                                                        newForm[idx] = { ...newForm[idx], dateGiven: e.target.value };
                                                        setImmunizationForm(newForm);
                                                    }}
                                                    className="w-full text-xs p-1.5 rounded border border-gray-200"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                ))}
                                <div className="flex justify-end gap-2 pt-1">
                                    <button 
                                        onClick={handleCancelImmunizations}
                                        className="px-3 py-1.5 text-xs font-bold text-gray-500 hover:bg-gray-100 rounded-lg transition-colors"
                                    >
                                        Cancel
                                    </button>
                                    <button 
                                        onClick={handleSaveImmunizations}
                                        className="px-3 py-1.5 bg-primary-400 text-white rounded-lg text-xs font-bold hover:bg-primary-500 shadow-sm transition-all"
                                    >
                                        Save Updates
                                    </button>
                                </div>
                            </div>
                         ) : (
                             healthRecord?.immunizations && healthRecord.immunizations.length > 0 && (
                                <div className="mt-4 bg-white rounded-xl border border-gray-100 divide-y divide-gray-50">
                                    {healthRecord.immunizations.map(imm => (
                                        <div key={imm.id} className="p-3 flex justify-between items-center">
                                            <div>
                                                <p className="text-sm font-bold text-gray-700">{imm.name}</p>
                                                <p className="text-xs text-gray-400">Due: {imm.dueDate}</p>
                                            </div>
                                            <div className="text-right">
                                                {imm.status === 'COMPLIANT' ? (
                                                    <span className="text-xs font-bold text-green-600 bg-green-50 px-2 py-0.5 rounded">
                                                        ✔ {imm.dateGiven}
                                                    </span>
                                                ) : (
                                                    <span className="text-xs font-bold text-red-500 bg-red-50 px-2 py-0.5 rounded">
                                                        ⚠ Overdue
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                             )
                         )}
                    </div>

                    {/* Medication Management */}
                    <div>
                        <div className="flex justify-between items-center mb-3">
                             <h4 className="font-display font-bold text-gray-800">Active Medications</h4>
                             <button className="text-xs font-bold bg-primary-100 text-primary-600 px-3 py-1.5 rounded-lg hover:bg-primary-200 transition-colors">
                                 + Add New
                             </button>
                        </div>

                        {healthRecord?.medications && healthRecord.medications.length > 0 ? (
                            <div className="space-y-3">
                                {healthRecord.medications.map(med => (
                                    <div key={med.id} className="bg-white border border-primary-100 rounded-2xl p-4 shadow-sm relative overflow-hidden">
                                        <div className="absolute top-0 left-0 w-1 h-full bg-accent-300"></div>
                                        <div className="flex justify-between items-start mb-2 pl-2">
                                            <div>
                                                <h5 className="font-bold text-gray-800">{med.name} <span className="text-gray-400 font-normal text-xs">({med.dosage})</span></h5>
                                                <p className="text-xs text-primary-500 font-bold uppercase tracking-wide">{med.frequency}</p>
                                            </div>
                                            <button 
                                                onClick={() => handleLogMedication(med.id, med.name)}
                                                disabled={loggingMedicationId === med.id}
                                                className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors border ${
                                                    loggingMedicationId === med.id 
                                                    ? 'bg-gray-100 text-gray-400 border-gray-200 cursor-wait'
                                                    : 'bg-primary-50 text-primary-600 hover:bg-primary-100 border-primary-200'
                                                }`}
                                            >
                                                {loggingMedicationId === med.id ? 'Saving...' : '💊 Log Dose'}
                                            </button>
                                        </div>
                                        {med.instructions && (
                                            <p className="text-xs text-gray-500 italic mb-2 pl-2 border-l-2 border-gray-100 ml-2">"{med.instructions}"</p>
                                        )}
                                        <div className="flex items-center gap-2 text-[10px] text-gray-400 pl-2">
                                            <span>🕒 Last given:</span>
                                            <span className="font-bold text-gray-600">{med.lastAdministered || 'Not yet administered today'}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-6 border-2 border-dashed border-gray-100 rounded-xl">
                                <p className="text-gray-400 text-sm">No active medications.</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

