  const [enrollmentTab, setEnrollmentTab] = useState<'PENDING' | 'WAITLIST'>('PENDING');

  // Add Classroom State
  const [isAddingClassroom, setIsAddingClassroom] = useState(false);
  const [newClassroomName, setNewClassroomName] = useState('');

  // Edit Mode State (Full Profile)
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editFormData, setEditFormData] = useState<Partial<Child>>({});

  // Inline Notes Edit State
  const [isEditingNotes, setIsEditingNotes] = useState(false);
  const [notesBuffer, setNotesBuffer] = useState('');

  // Add Guardian State
  const [isAddingGuardian, setIsAddingGuardian] = useState(false);
  const [newGuardianData, setNewGuardianData] = useState<Partial<Guardian>>({});

  // Health Edit State
  const [isEditingHealth, setIsEditingHealth] = useState(false);
  const [healthEditForm, setHealthEditForm] = useState<{allergies: string, bloodType: string}>({allergies: '', bloodType: ''});

  // Immunization Edit State
  const [isEditingImmunizations, setIsEditingImmunizations] = useState(false);
  const [immunizationForm, setImmunizationForm] = useState<Immunization[]>([]);

  // Medication Log State
  const [loggingMedicationId, setLoggingMedicationId] = useState<string | null>(null);

  // Payment Processing State
  const [processingInvoiceId, setProcessingInvoiceId] = useState<string | null>(null);

  // Health Analytics Modal State
  const [isHealthAnalyticsOpen, setIsHealthAnalyticsOpen] = useState(false);

  // Derived State
  const filteredChildren = activeSection === 'DAILY_OPS' 
    ? children.filter(c => c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED')
    : children.filter(c => c.enrollmentStatus === enrollmentTab);

  const selectedChild = children.find(c => c.id === selectedChildId);
  const currentClassroom = classrooms.find(c => c.id === selectedClassroomId);

  // Helper function to parse money string to number
  const parseMoney = (str: string) => parseFloat(str.replace(/[^0-9.-]+/g,""));

  // Calculate Real-time Metrics
  const calculateMetrics = () => {
      const totalChildren = children.filter(c => c.enrollmentStatus === 'ENROLLED').length;
      const present = children.filter(c => c.status === 'PRESENT' && c.enrollmentStatus === 'ENROLLED').length;
      const absent = children.filter(c => c.status === 'ABSENT' && c.enrollmentStatus === 'ENROLLED').length;
      const checkedOut = children.filter(c => c.status === 'CHECKED_OUT' && c.enrollmentStatus === 'ENROLLED').length;

      const totalCapacity = classrooms.reduce((acc, room) => acc + room.capacity, 0);

      // Billing Calculation
      const allInvoices = Object.values(invoicesMap).flat() as Invoice[];
      const totalRevenue = allInvoices
          .filter(i => i.status === 'PAID')
          .reduce((acc, i) => acc + parseMoney(i.amount), 0);
      const pendingRevenue = allInvoices
          .filter(i => i.status === 'PENDING')
          .reduce((acc, i) => acc + parseMoney(i.amount), 0);
      const overdueRevenue = allInvoices
          .filter(i => i.status === 'OVERDUE')
          .reduce((acc, i) => acc + parseMoney(i.amount), 0);

      return {
          attendance: { 
              total: totalChildren, 
              present, 
              absent, 
              checkedOut, 
              rate: totalChildren ? Math.round((present / totalChildren) * 100) : 0 
          },
          capacity: { 
              total: totalCapacity, 
              enrolled: totalChildren, 
              utilization: totalCapacity ? Math.round((totalChildren / totalCapacity) * 100) : 0 
          },
          billing: { 
              totalRevenue, 
              pendingRevenue, 
              overdueRevenue 
          },
          classrooms: classrooms.map(room => {
               const roomChildren = children.filter(c => c.classroomId === room.id && c.enrollmentStatus === 'ENROLLED');
               const roomPresent = roomChildren.filter(c => c.status === 'PRESENT').length;
               return { 
                   ...room, 
                   actualEnrolled: roomChildren.length, 
                   presentCount: roomPresent,
                   utilization: Math.round((roomChildren.length / room.capacity) * 100)
               };
          })
      };
  }

  const metrics = calculateMetrics();

  // Effects
  useEffect(() => {
    // Reset editing states when switching children
    setIsEditingProfile(false);
    setIsEditingNotes(false);
    setIsAddingGuardian(false);
    setIsEditingHealth(false);
    setHealthEditForm({allergies: '', bloodType: ''});
    setIsEditingImmunizations(false);
    setImmunizationForm([]);
    setNewGuardianData({});
    setLoggingMedicationId(null);
    setProcessingInvoiceId(null);
  }, [selectedChildId]);

  useEffect(() => {
      // Reset selection when switching sections
      setSelectedChildId(null);
  }, [activeSection, enrollmentTab]);

  // --- Handlers ---

  const navigateTo = (section: AppSection) => {
    if (section === activeSection) return;
    setNavHistory(prev => [...prev, section]);
    setActiveSection(section);
    setSelectedChildId(null); // Clear selection when changing main section
  };

  const goBack = () => {
    if (navHistory.length > 1) {
        const newHistory = [...navHistory];
        newHistory.pop(); // Remove current
        const prevSection = newHistory[newHistory.length - 1];
        setNavHistory(newHistory);
        setActiveSection(prevSection);
        setSelectedChildId(null);
    }
  };

  const goHome = () => {
    setNavHistory(['DAILY_OPS']);
    setActiveSection('DAILY_OPS');
    setSelectedChildId(null);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
  };

  const handleEnrollChild = (childId: string, classroomId: string) => {
      const room = classrooms.find(r => r.id === classroomId);
      if (!room) return;

      setChildren(prev => prev.map(c => 
          c.id === childId 
            ? { ...c, enrollmentStatus: 'ENROLLED', classroomId: classroomId, classroom: room.name } 
            : c
      ));

      setToast({ message: `Successfully enrolled child in ${room.name}`, type: 'success' });
      setTimeout(() => setToast(null), 3000);
      setSelectedChildId(null);
  };

  const handleMoveToWaitlist = (childId: string) => {
      setChildren(prev => prev.map(c => 
          c.id === childId ? { ...c, enrollmentStatus: 'WAITLIST' } : c
      ));
      setToast({ message: 'Moved applicant to Waitlist', type: 'success' });
      setTimeout(() => setToast(null), 3000);
      setSelectedChildId(null);
  };

  const handleRejectChild = (childId: string) => {
      if(window.confirm("Are you sure you want to reject this application?")) {
        setChildren(prev => prev.map(c => 
            c.id === childId ? { ...c, enrollmentStatus: 'ARCHIVED' } : c
        ));
        setToast({ message: 'Application archived', type: 'success' });
        setTimeout(() => setToast(null), 3000);
        setSelectedChildId(null);
      }
  };

  const handleSaveClassroom = () => {
    if (newClassroomName.trim()) {
      const newId = `room_${Date.now()}`;
      const newClassroom: Classroom = {
        id: newId,
        name: newClassroomName.trim(),
        enrolled: 0,
        capacity: 15, // Default capacity
        staff: []
      };

      setClassrooms(prev => [...prev, newClassroom]);
      setSelectedClassroomId(newId);
      setSelectedChildId(null);

      // Reset state
      setIsAddingClassroom(false);
      setNewClassroomName('');
    }
  };

  const handleQuickAdd = () => {
    if (!currentClassroom) return;

    const newChild: Child = {
      id: `new_${Date.now()}`,
      firstName: 'New',
      lastName: 'Student',
      avatarUrl: `https://api.dicebear.com/7.x/micah/svg?seed=${Date.now()}&backgroundColor=b6e3f4`,
      classroom: currentClassroom.name,
      classroomId: currentClassroom.id,
      status: 'ABSENT',
      enrollmentStatus: 'ENROLLED',
      dob: '',
      notes: '',
      allergies: [],
    };

    setChildren(prev => [newChild, ...prev]);
    setSelectedChildId(newChild.id);
    setActiveDetailTab('PROFILE'); // Switch to profile tab immediately
    setEditFormData(newChild); // Pre-fill form
    setIsEditingProfile(true); // Enter edit mode immediately
  };

  const handleCheckIn = () => {
    // Check in all absent children in the current classroom
    let count = 0;
    const newActivities: Activity[] = [];
    const updatedChildren = children.map(child => {
      if (child.classroomId === selectedClassroomId && child.status === 'ABSENT' && child.enrollmentStatus === 'ENROLLED') {
        count++;
        // Generate Check-in Activity
        newActivities.push({
            id: `act_${child.id}_${Date.now()}`,
            childId: child.id,
            type: ActivityType.CHECK_IN,
            title: 'Checked In',
            timestamp: new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
            authorName: 'You',
        });
        return { ...child, status: 'PRESENT', lastActivityTime: 'Just now' };
      }
      return child;
    });

    if (count > 0) {
      setChildren(updatedChildren as Child[]);
      setActivities(prev => [...newActivities, ...prev]);
      alert(`Checked in ${count} children to ${currentClassroom?.name}!`);
    } else {
      alert(`Everyone in ${currentClassroom?.name} is already checked in.`);
    }
  };

  const handleChildStatusChange = (status: 'PRESENT' | 'ABSENT' | 'CHECKED_OUT') => {
    if (!selectedChild) return;

    // Add confirmation before checking out
    if (status === 'CHECKED_OUT') {
      const confirmed = window.confirm(`Are you sure you want to check out ${selectedChild.firstName}?`);
      if (!confirmed) return;
    }

    // Log Activity
    const newActivity: Activity = {
        id: `act_${Date.now()}`,
        childId: selectedChild.id,
        type: status === 'CHECKED_OUT' ? ActivityType.CHECK_OUT : ActivityType.CHECK_IN,
        title: status === 'CHECKED_OUT' ? 'Checked Out' : 'Checked In',
        timestamp: new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
        authorName: 'You',
        description: status === 'CHECKED_OUT' ? 'Picked up by guardian.' : 'Arrived at center.'
    };
    setActivities(prev => [newActivity, ...prev]);

    setChildren(prev => prev.map(c => 
        c.id === selectedChild.id ? { ...c, status: status, lastActivityTime: 'Just now' } : c
    ));
  };

  // Health Handlers
  const handleLogMedication = (medId: string, medName: string) => {
    if (!selectedChild) return;

    setLoggingMedicationId(medId);

    // Simulate Network Request
    setTimeout(() => {
        // Log the activity
        const newActivity: Activity = {
          id: `act_med_${Date.now()}`,
          childId: selectedChild.id,
          type: ActivityType.MEDICATION,
          title: 'Medication Administered',
          description: `Administered ${medName}`,
          timestamp: new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
          authorName: 'You'
        };
        setActivities(prev => [newActivity, ...prev]);

        // Update medication last administered time
        setHealthRecordsMap(prev => {
            const record = prev[selectedChild.id];
            if (!record) return prev;

            return {
                ...prev,
                [selectedChild.id]: {
                    ...record,
                    medications: record.medications.map(m => 
                        m.id === medId 
                        ? { ...m, lastAdministered: new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) } 
                        : m
                    )
                }
            };
        });

        setLoggingMedicationId(null);
        setToast({ message: `Logged dose for ${medName}`, type: 'success' });
        setTimeout(() => setToast(null), 3000);
    }, 800);
  };

  const handleEditHealth = () => {
    if (!selectedChild) return;
    const healthRecord = healthRecordsMap[selectedChild.id];
    setHealthEditForm({
        allergies: selectedChild.allergies?.join(', ') || '',
        bloodType: healthRecord?.bloodType || ''
    });
    setIsEditingHealth(true);
  };

  const handleCancelHealthEdit = () => {
    setIsEditingHealth(false);
    setHealthEditForm({allergies: '', bloodType: ''});
  };

  const handleSaveHealth = () => {
    if (!selectedChild) return;

    // 1. Update Child (Allergies)
    const newAllergies = healthEditForm.allergies.split(',').map(s => s.trim()).filter(s => s !== '');

    setChildren(prev => prev.map(c => 
        c.id === selectedChild.id ? { ...c, allergies: newAllergies } : c
    ));

    // 2. Update Health Record (Blood Type)
    setHealthRecordsMap(prev => {
        const existing = prev[selectedChild.id] || { childId: selectedChild.id, immunizations: [], medications: [] };
        return {
            ...prev,
            [selectedChild.id]: {
                ...existing,
                bloodType: healthEditForm.bloodType
            }
        };
    });

    setIsEditingHealth(false);
    setToast({ message: 'Health profile updated', type: 'success' });
    setTimeout(() => setToast(null), 3000);
  };

  const handleEditImmunizations = () => {
    if (!selectedChild) return;
    const healthRecord = healthRecordsMap[selectedChild.id];
    if (healthRecord?.immunizations) {
        // Deep copy to avoid mutating state directly
        setImmunizationForm(JSON.parse(JSON.stringify(healthRecord.immunizations)));
        setIsEditingImmunizations(true);
    }
  };

  const handleCancelImmunizations = () => {
    setIsEditingImmunizations(false);
    setImmunizationForm([]);
  };

  const handleSaveImmunizations = () => {
    if (!selectedChild) return;
    setHealthRecordsMap(prev => {
        const existing = prev[selectedChild.id] || { childId: selectedChild.id, immunizations: [], medications: [] };
        return {
            ...prev,
            [selectedChild.id]: {
                ...existing,
                immunizations: immunizationForm
            }
        };
    });
    setIsEditingImmunizations(false);
    setToast({ message: 'Immunization records updated', type: 'success' });
    setTimeout(() => setToast(null), 3000);
  };

  // Full Profile Edit Handlers
  const handleEditProfile = () => {
    if (selectedChild) {
      setEditFormData({ ...selectedChild });
      setIsEditingProfile(true);
      setIsEditingNotes(false); // Close inline notes if open
    }
  };

  const handleSaveProfile = () => {
    if (!selectedChild) return;

    const updatedChildren = children.map(c => 
      c.id === selectedChild.id ? { ...c, ...editFormData } as Child : c
    );
    setChildren(updatedChildren);
    setIsEditingProfile(false);
  };

  const handleCancelEdit = () => {
    setIsEditingProfile(false);
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditFormData(prev => ({ ...prev, avatarUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  // Inline Notes Edit Handlers
  const handleStartEditNotes = () => {
    if (selectedChild) {
      setNotesBuffer(selectedChild.notes || '');
      setIsEditingNotes(true);
    }
  };

  const handleSaveNotes = () => {
    if (!selectedChild) return;
    const updatedChildren = children.map(c => 
      c.id === selectedChild.id ? { ...c, notes: notesBuffer } : c
    );
    setChildren(updatedChildren);
    setIsEditingNotes(false);
  };

  // Add Guardian Handlers
  const handleSaveGuardian = () => {
    if (!selectedChild || !newGuardianData.name || !newGuardianData.relation) return;

    const newGuardian: Guardian = {
      id: `g_${Date.now()}`,
      name: newGuardianData.name || 'Unknown',
      relation: newGuardianData.relation || 'Guardian',
      phone: newGuardianData.phone || '',
      email: newGuardianData.email || '',
      avatarUrl: `https://ui-avatars.com/api/?name=${newGuardianData.name}&background=random&color=fff`,
    };

    setGuardiansMap(prev => ({
      ...prev,
      [selectedChild.id]: [...(prev[selectedChild.id] || []), newGuardian]
    }));

    setIsAddingGuardian(false);
    setNewGuardianData({});
  };

  const handleCancelGuardian = () => {
    setIsAddingGuardian(false);
    setNewGuardianData({});
  };

  // Payment Handler
  const handlePayInvoice = (invoiceId: string) => {
    if (!selectedChild) return;

    setProcessingInvoiceId(invoiceId);

    // Simulate API Network Delay
    setTimeout(() => {
        setInvoicesMap(prev => {
            const childInvoices = prev[selectedChild.id] || [];
            return {
                ...prev,
                [selectedChild.id]: childInvoices.map(inv => 
                    inv.id === invoiceId ? { ...inv, status: 'PAID' } : inv
                )
            };
        });
        setProcessingInvoiceId(null);

        // Show Success Toast
        setToast({ message: 'Payment successful! Invoice marked as PAID.', type: 'success' });
        setTimeout(() => setToast(null), 3000);
    }, 1500);
  };

  // --- Components ---

  const SidebarContent = () => (
    <div className="space-y-6">

      <div>
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 pl-2">Centers</h3>
        <div className="space-y-1">
          {CENTERS.map(center => (
            <div 
                key={center.id}
                onClick={() => {
                    setSelectedCenterId(center.id);
                    setToast({ message: `Switched to ${center.name}`, type: 'success' });
                    setTimeout(() => setToast(null), 2000);
                }}
                className={`px-3 py-2 rounded-lg font-medium text-sm cursor-pointer transition-colors ${
                    selectedCenterId === center.id
                    ? 'bg-primary-100 text-primary-500 font-semibold shadow-sm'
                    : 'text-gray-600 hover:bg-gray-50'
                }`}
            >
                {center.name}
            </div>
          ))}
        </div>
      </div>

      <div>
          <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 pl-2">Management</h3>
          <div className="space-y-1">
              <div 
                  onClick={() => {
                      navigateTo('ENROLLMENT');
                      setEnrollmentTab('PENDING');
                  }}
                  className={`flex items-center justify-between px-3 py-2 rounded-lg font-medium text-sm cursor-pointer transition-colors ${
                      activeSection === 'ENROLLMENT'
                      ? 'bg-primary-100 text-primary-500 font-semibold shadow-sm'
                      : 'text-gray-600 hover:bg-gray-50'
                  }`}
              >
                  <span>Enrollment</span>
                  {children.filter(c => c.enrollmentStatus === 'PENDING').length > 0 && (
                      <span className="bg-purple-100 text-purple-600 px-1.5 py-0.5 rounded text-[10px] font-bold">
                          {children.filter(c => c.enrollmentStatus === 'PENDING').length}
                      </span>
                  )}
              </div>
          </div>
      </div>

      {activeSection === 'DAILY_OPS' && (
        <div>
            <div className="flex justify-between items-center mb-3 pl-2 pr-2">
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Classrooms</h3>
                {!isAddingClassroom && (
                <button
                    onClick={() => setIsAddingClassroom(true)}
                    className="text-xs text-primary-400 hover:text-primary-600 font-bold px-2 py-1 hover:bg-primary-50 rounded transition-colors"
                    title="Add New Classroom"
                >
                    + Add
                </button>
                )}
            </div>

            {isAddingClassroom && (
            <div className="mx-2 mb-3 bg-white p-3 rounded-lg border border-primary-200 shadow-sm animate-fade-in">
                <input 
                type="text" 
                value={newClassroomName}
                onChange={(e) => setNewClassroomName(e.target.value)}
                placeholder="Room Name (e.g. 🦁 Lions)"
                className="w-full text-sm border border-gray-300 rounded p-1.5 mb-2 focus:ring-2 focus:ring-primary-300 focus:outline-none"
                autoFocus
                />
                <div className="flex justify-end gap-2">
                <button 
                    onClick={() => {
                    setIsAddingClassroom(false);
                    setNewClassroomName('');
                    }}
                    className="text-[10px] font-bold text-gray-500 hover:text-gray-700 px-2 py-1"
                >
                    Cancel
                </button>
                <button 
                    onClick={handleSaveClassroom}
                    disabled={!newClassroomName.trim()}
                    className="text-[10px] font-bold bg-primary-400 text-white px-3 py-1 rounded hover:bg-primary-500 disabled:opacity-50"
                >
                    Save
                </button>
                </div>
            </div>
            )}

            <div className="space-y-1">
            {classrooms.map(room => {
                const isActive = room.id === selectedClassroomId;
                const enrolledInRoom = children.filter(c => c.classroomId === room.id && c.enrollmentStatus === 'ENROLLED').length;

                return (
                <div 
                    key={room.id}
                    onClick={() => {
                    setSelectedClassroomId(room.id);
                    setSelectedChildId(null); // Deselect child when changing rooms
                    }}
                    className={`
                    flex items-center justify-between px-3 py-2 rounded-lg text-sm cursor-pointer transition-all duration-200
                    ${isActive 
                        ? 'bg-white border border-gray-100 shadow-sm text-gray-900 font-bold' 
                        : 'text-gray-600 hover:bg-gray-50 font-medium border border-transparent'}
                    `}
                >
                    <span className="truncate max-w-[140px]">{room.name}</span>
                    <span className={`
                    text-[10px] px-1.5 py-0.5 rounded font-bold shrink-0
                    ${isActive ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}
                    `}>
                    {enrolledInRoom}/{room.capacity}
                    </span>
                </div>
                );
            })}
            </div>
        </div>
      )}

      {/* Control Center Widget */}
      <div 
        onClick={() => setIsHealthAnalyticsOpen(true)}
        className="mt-8 p-4 bg-gray-50 rounded-xl border border-gray-100 cursor-pointer hover:bg-white hover:shadow-md transition-all group"
      >
        <div className="flex justify-between items-start mb-2">
            <h4 className="text-xs font-bold text-gray-500">Center Health</h4>
            <span className="text-[10px] font-bold bg-primary-100 text-primary-600 px-1.5 py-0.5 rounded">View Analytics</span>
        </div>
        <div className="flex justify-between items-end">
          <div>
            <div className="text-2xl font-display font-bold text-gray-800 group-hover:text-primary-500 transition-colors">
                {metrics.attendance.rate}%
            </div>
            <div className="text-[10px] text-gray-400 flex items-center gap-1">
                Attendance 
                <span className={metrics.attendance.rate > 85 ? 'text-green-500' : 'text-orange-500'}>
                    {metrics.attendance.rate > 85 ? '▲ Good' : '▼ Low'}
                </span>
            </div>
          </div>
          <div className={`h-8 w-8 rounded-full flex items-center justify-center text-xs ${metrics.attendance.rate > 85 ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-600'}`}>
             {metrics.attendance.rate > 85 ? '👍' : '⚠️'}
          </div>
        </div>
      </div>
    </div>
  );

  const ListPanelContent = () => (
    <div className="space-y-4">

      {activeSection === 'DAILY_OPS' ? (
          <>
            <div className="flex items-center justify-between mb-4">
                <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">
                    {filteredChildren.length} Enrolled
                </span>
            </div>
            {filteredChildren.length === 0 && (
                 <div className="text-center py-10 text-gray-400">
                    <div className="text-4xl mb-2">🍃</div>
                    <p>No children in this room yet.</p>
                    <p className="text-xs mt-2">Use "Quick Add" to enroll someone.</p>
                 </div>
            )}
          </>
      ) : (
          <div className="mb-4">
              {/* Enrollment Tabs */}
              <div className="flex bg-gray-100 rounded-lg p-1 mb-4">
                  <button 
                      onClick={() => setEnrollmentTab('PENDING')}
                      className={`flex-1 py-1.5 rounded-md text-xs font-bold transition-all ${
                          enrollmentTab === 'PENDING' ? 'bg-white text-primary-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                      }`}
                  >
                      Pending ({children.filter(c => c.enrollmentStatus === 'PENDING').length})
                  </button>
                  <button 
                      onClick={() => setEnrollmentTab('WAITLIST')}
                      className={`flex-1 py-1.5 rounded-md text-xs font-bold transition-all ${
                          enrollmentTab === 'WAITLIST' ? 'bg-white text-primary-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                      }`}
                  >
                      Waitlist ({children.filter(c => c.enrollmentStatus === 'WAITLIST').length})
                  </button>
              </div>
              {filteredChildren.length === 0 && (
                  <div className="text-center py-10 text-gray-400">
                      <p>No {enrollmentTab.toLowerCase()} applications.</p>
                  </div>
              )}
          </div>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredChildren.map(child => (
          <NestCard 
            key={child.id} 
            child={child} 
            selected={selectedChildId === child.id}
            onClick={() => setSelectedChildId(child.id)}
          />
        ))}
      </div>
