                                <div className="flex justify-end gap-2 mt-2">
                                    <button onClick={handleCancelGuardian} className="text-xs font-bold text-gray-500 px-2 py-1">Cancel</button>
                                    <button onClick={handleSaveGuardian} className="text-xs font-bold bg-primary-400 text-white px-3 py-1 rounded">Save</button>
