                                                text-[10px] font-bold px-3 py-1.5 rounded-full uppercase transition-all
                                                ${inv.status === 'OVERDUE' ? 'bg-red-100 text-red-600 hover:bg-red-200' : 'bg-orange-100 text-orange-600 hover:bg-orange-200'}
                                            `}
                                        >
                                            {processingInvoiceId === inv.id ? '...' : `Pay ${inv.status}`}
                                        </button>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
      </div>
    );
  };

  return (
    <>
      {!isAuthenticated ? (
        <LoginScreen onLogin={() => setIsAuthenticated(true)} />
      ) : (
        <AdminLayout 
          sidebar={<SidebarContent />}
          listPanel={<ListPanelContent />}
          detailPanel={<DetailPanelContent />}
          onCheckIn={handleCheckIn}
          onQuickAdd={handleQuickAdd}
          onLogout={handleLogout}
          onGoHome={goHome}
          onGoBack={goBack}
          canGoBack={navHistory.length > 1}
        />
      )}

      {/* Toast Notification */}
      {toast && (
        <div className={`fixed bottom-6 right-6 px-6 py-3 rounded-xl shadow-lg font-bold text-white animate-fade-in-up z-50 ${toast.type === 'success' ? 'bg-gray-800' : 'bg-red-500'}`}>
            {toast.type === 'success' ? '✅' : '❌'} {toast.message}
        </div>
      )}

      {/* Health Analytics Modal (Simplified) */}
      {isHealthAnalyticsOpen && (
        <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setIsHealthAnalyticsOpen(false)}>
