                         </div>
                     </div>
                     <div className="bg-gray-50 p-4 rounded-xl">
                         <h4 className="text-xs font-bold text-gray-400 uppercase mb-2">Today's Attendance</h4>
                         <p className="text-2xl font-bold text-gray-800">{metrics.attendance.present} <span className="text-sm text-gray-400 font-normal">Present</span></p>
                         <p className="text-sm text-gray-500">{metrics.attendance.absent} Absent • {metrics.attendance.checkedOut} Checked Out</p>
                     </div>
                     <div className="bg-gray-50 p-4 rounded-xl">
                         <h4 className="text-xs font-bold text-gray-400 uppercase mb-2">Revenue Pulse</h4>
                         <div className="flex justify-between items-end">
                            <div>
                                <p className="text-sm text-gray-500">Pending</p>
                                <p className="text-lg font-bold text-orange-500">${metrics.billing.pendingRevenue.toLocaleString()}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm text-gray-500">Overdue</p>
                                <p className="text-lg font-bold text-red-500">${metrics.billing.overdueRevenue.toLocaleString()}</p>
                            </div>
                         </div>
                     </div>
                </div>
            </div>
        </div>
      )}
    </>
  );
};

