                </div>

                <div className="pt-6 border-t border-gray-100 flex items-center justify-between">
                   <p className="text-[10px] text-gray-400 font-bold uppercase">Member since {new Date(selectedStaff.joinedDate).getFullYear()}</p>
                   <button className="text-xs font-bold text-accent-300 hover:text-accent-400">View Paystubs →</button>
                </div>
              </div>
            )}
          </div>
        </div>
