        </div>
      );
    }

    return (
      <div className="flex flex-col h-full animate-in fade-in duration-300">
        <div className="bg-white shrink-0 z-20">
            <div className="h-40 bg-primary-100 relative overflow-hidden group">
                <img src={`https://picsum.photos/800/400?random=${selectedChild.id}`} className="w-full h-full object-cover opacity-40 mix-blend-multiply transition-transform duration-700 group-hover:scale-105" />
                <div className="absolute -bottom-10 left-6">
                    <img src={selectedChild.avatarUrl} className="w-24 h-24 rounded-full border-4 border-white shadow-md object-cover bg-white" />
                </div>
            </div>

            <div className="mt-12 px-6">
                <div className="flex justify-between items-start">
                    <div>
                        <h2 className="text-2xl font-display font-bold text-gray-800">{selectedChild.firstName} {selectedChild.lastName}</h2>
                        <p className="text-gray-500 text-sm font-medium">{selectedChild.classroom}</p>
                    </div>
                </div>

                <div className="flex gap-1 mt-6 border-b border-gray-100 overflow-x-auto no-scrollbar">
                    {['TIMELINE', 'HEALTH', 'PROFILE', 'GUARDIANS', 'BILLING'].map(tab => (
                        <button key={tab} onClick={() => setActiveDetailTab(tab as DetailTab)} className={`px-4 py-3 text-sm font-bold relative transition-colors whitespace-nowrap ${activeDetailTab === tab ? 'text-primary-500' : 'text-gray-400 hover:text-gray-600'}`}>
                            {tab.charAt(0) + tab.slice(1).toLowerCase()}
                            {activeDetailTab === tab && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-primary-300 rounded-t-full" />}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto bg-white p-6">
           {activeDetailTab === 'TIMELINE' && activities.filter(a => a.childId === selectedChild.id).map(act => <ActivityFeedItem key={act.id} activity={act} />)}
           {activeDetailTab === 'PROFILE' && <div className="text-sm text-gray-500">{selectedChild.notes || 'No notes available.'}</div>}
           {/* Add other tabs as needed */}
        </div>
      </div>
    );
  }

  if (!isAuthenticated) return <LoginScreen onLogin={() => setIsAuthenticated(true)} />;

  return (
    <>
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={handleLogout}
        onGoHome={() => navigateTo('DAILY_OPS')}
        onGoBack={goBack}
        canGoBack={navHistory.length > 1}
      />
      {toast && (
        <div className={`fixed bottom-6 right-6 px-6 py-4 rounded-xl shadow-xl flex items-center gap-3 animate-in slide-in-from-bottom-4 fade-in duration-300 z-50 ${toast.type === 'success' ? 'bg-green-600 text-white' : 'bg-red-500 text-white'}`}>
            <span className="font-bold">{toast.message}</span>
        </div>
      )}
    </>
  );
};

