                    <span className="text-[10px] bg-gray-100 px-1.5 py-0.5 rounded text-gray-500">{room.enrolled}/{room.capacity}</span>
                </div>
            ))}
            </div>
        </div>
      )}

      {/* Analytics Widget */}
      <div onClick={() => setIsHealthAnalyticsOpen(true)} className="mt-8 p-4 bg-gray-50 rounded-xl border border-gray-100 cursor-pointer hover:bg-white hover:shadow-md transition-all">
          <div className="flex justify-between items-start mb-2"><h4 className="text-xs font-bold text-gray-500">Center Attendance</h4></div>
          <div className="text-2xl font-display font-bold text-gray-800">{metrics.attendanceRate}%</div>
          <p className="text-[10px] text-gray-400">Click for full health analytics</p>
      </div>
    </div>
  );

  const ListPanelContent = () => (
    <div className="space-y-6">
      {activeSection === 'TEAM' ? (
        <div className="space-y-4">
           <h2 className="text-xl font-display font-bold text-gray-800">Staff Directory</h2>
           <div className="grid gap-3">
             {staff.map(s => (
               <div key={s.id} onClick={() => { setSelectedStaffId(s.id); setSelectedChildId(null); }} className={`p-4 bg-white rounded-nest border cursor-pointer transition-all hover:shadow-md flex items-center gap-4 ${selectedStaffId === s.id ? 'ring-2 ring-primary-300' : 'border-gray-100'}`}>
                 <img src={s.avatarUrl} className="w-12 h-12 rounded-full bg-primary-50" />
                 <div><h4 className="font-bold text-gray-800">{s.name}</h4><p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{s.role}</p></div>
               </div>
             ))}
           </div>
        </div>
      ) : activeSection === 'ENROLLMENT' ? (
        <div className="space-y-4">
            <div className="flex bg-gray-100 rounded-lg p-1">
                <button onClick={() => setEnrollmentTab('PENDING')} className={`flex-1 py-1.5 rounded-md text-xs font-bold ${enrollmentTab === 'PENDING' ? 'bg-white text-primary-600' : 'text-gray-500'}`}>Pending</button>
                <button onClick={() => setEnrollmentTab('WAITLIST')} className={`flex-1 py-1.5 rounded-md text-xs font-bold ${enrollmentTab === 'WAITLIST' ? 'bg-white text-primary-600' : 'text-gray-500'}`}>Waitlist</button>
            </div>
            {filteredChildren.map(child => (
              <NestCard key={child.id} child={child} selected={selectedChildId === child.id} onClick={() => { setSelectedChildId(child.id); setSelectedStaffId(null); }} />
            ))}
        </div>
      ) : (
        <>
          <div className="space-y-2">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest pl-1">Teachers in {currentClassroom?.name}</h3>
            <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
               {filteredStaff.map(s => (
                 <div key={s.id} onClick={() => { setSelectedStaffId(s.id); setSelectedChildId(null); }} className="flex-shrink-0 flex items-center gap-2 bg-white border border-gray-100 px-3 py-2 rounded-full cursor-pointer hover:bg-primary-50 transition-colors shadow-sm">
                   <img src={s.avatarUrl} className="w-6 h-6 rounded-full" />
                   <span className="text-xs font-bold text-gray-700 whitespace-nowrap">{s.name}</span>
                 </div>
               ))}
            </div>
          </div>
          <div className="space-y-4">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest pl-1">Children</h3>
            {filteredChildren.map(child => (
              <NestCard key={child.id} child={child} selected={selectedChildId === child.id} onClick={() => { setSelectedChildId(child.id); setSelectedStaffId(null); }} />
            ))}
          </div>
        </>
      )}
    </div>
  );

  const DetailPanelContent = () => {
    // STAFF DETAIL VIEW
    if (selectedStaff) {
      return (
        <div className="flex flex-col h-full bg-white">
          <div className="h-40 bg-accent-300 relative">
             <div className="absolute -bottom-8 left-8">
               <img src={selectedStaff.avatarUrl} className="w-24 h-24 rounded-blob border-4 border-white shadow-xl bg-white" />
             </div>
          </div>
          <div className="pt-16 px-8 pb-8 flex-1 overflow-y-auto">
            <div className="flex justify-between items-start mb-6">
              <div><h2 className="text-2xl font-display font-bold text-gray-800">{selectedStaff.name}</h2><p className="text-primary-500 font-bold uppercase text-xs tracking-widest">{selectedStaff.role}</p></div>
              {!isEditingStaff && <button onClick={() => { setIsEditingStaff(true); setEditFormData({...selectedStaff}); }} className="text-xs font-bold text-primary-400 px-3 py-1.5 bg-primary-50 rounded-lg">Edit Profile</button>}
            </div>
            {isEditingStaff ? (
              <div className="space-y-4">
                 <input type="text" value={editFormData.phone} onChange={e => setEditFormData({...editFormData, phone: e.target.value})} className="w-full p-2 border rounded-lg text-sm" placeholder="Phone" />
                 <input type="email" value={editFormData.email} onChange={e => setEditFormData({...editFormData, email: e.target.value})} className="w-full p-2 border rounded-lg text-sm" placeholder="Email" />
                 <textarea rows={4} value={editFormData.bio} onChange={e => setEditFormData({...editFormData, bio: e.target.value})} className="w-full p-2 border rounded-lg text-sm" placeholder="Bio" />
