                    <button onClick={() => setIsEditingStaff(false)} className="px-4 py-2 text-sm font-bold text-gray-400">Cancel</button>
                    <button onClick={handleSaveStaff} className="px-6 py-2 bg-primary-400 text-white rounded-xl font-bold shadow-md">Save Changes</button>
                 </div>
              </div>
