              </div>
            )}
          </div>
        </div>
      );
    }

    // CHILD DETAIL VIEW
    if (selectedChild) {
      const healthRecord = healthRecordsMap[selectedChild.id];
      const childActivities = activities.filter(a => a.childId === selectedChild.id);
      const guardians = guardiansMap[selectedChild.id] || [];

      return (
        <div className="flex flex-col h-full bg-white">
          <div className="h-36 bg-primary-100 relative">
             <div className="absolute -bottom-8 left-6">
                <img src={selectedChild.avatarUrl} className="w-20 h-20 rounded-full border-4 border-white shadow-md bg-white object-cover" />
