                  <h4 className="text-xs font-bold text-red-700 uppercase mb-2">Allergies</h4>
                  <p className="text-sm font-bold text-red-800">{selectedChild.allergies?.join(', ') || 'None reported'}</p>
                </div>
                <div>
                  <h4 className="text-xs font-bold text-gray-400 uppercase mb-3">Medications</h4>
                  {healthRecord?.medications.map(med => (
                    <div key={med.id} className="bg-white border border-gray-100 p-4 rounded-xl shadow-sm mb-3">
                      <div className="flex justify-between items-start">
                        <div><p className="font-bold text-gray-800">{med.name} ({med.dosage})</p><p className="text-xs text-gray-500">{med.frequency}</p></div>
                        <button onClick={() => handleLogMedication(med.id, med.name)} disabled={loggingMedicationId === med.id} className={`text-xs font-bold px-3 py-1.5 rounded-lg ${loggingMedicationId === med.id ? 'bg-gray-100 text-gray-400' : 'bg-primary-50 text-primary-600 border border-primary-100'}`}>
                          {loggingMedicationId === med.id ? '...' : 'Log Dose'}
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {activeDetailTab === 'BILLING' && (
              <div className="space-y-4">
                 <div className="bg-gray-800 rounded-xl p-5 text-white">
                    <p className="text-xs text-gray-400 uppercase font-bold mb-1">Balance Due</p>
                    <p className="text-3xl font-display font-bold">$0.00</p>
                 </div>
                 {invoicesMap[selectedChild.id]?.map(inv => (
                   <div key={inv.id} className="flex justify-between items-center border p-4 rounded-xl">
                      <div><p className="font-bold text-gray-800">{inv.title}</p><p className="text-xs text-gray-400">{inv.date}</p></div>
                      <span className="font-mono font-bold text-green-600">{inv.amount}</span>
                   </div>
                 ))}
              </div>
            )}

            {activeDetailTab === 'GUARDIANS' && (
              <div className="space-y-3">
                {guardians.map(g => (
                  <div key={g.id} className="flex items-center gap-4 bg-white border p-4 rounded-xl">
                    <img src={g.avatarUrl} className="w-12 h-12 rounded-full" />
                    <div className="flex-1"><p className="font-bold text-gray-800">{g.name}</p><p className="text-xs text-primary-500 font-bold uppercase">{g.relation}</p></div>
                    <p className="text-xs text-gray-400">{g.phone}</p>
                  </div>
                ))}
              </div>
            )}

            {activeDetailTab === 'PROFILE' && (
              <div className="space-y-4">
                 <p className="text-sm text-gray-600 leading-relaxed bg-surface-50 p-4 rounded-xl italic">"{selectedChild.notes || 'No bio info.'}"</p>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="bg-gray-50 p-3 rounded-lg"><h5 className="text-[10px] text-gray-400 font-bold uppercase">DOB</h5><p className="font-medium text-sm">{selectedChild.dob}</p></div>
                    <div className="bg-gray-50 p-3 rounded-lg"><h5 className="text-[10px] text-gray-400 font-bold uppercase">Blood Type</h5><p className="font-medium text-sm">{healthRecord?.bloodType || 'Unknown'}</p></div>
                 </div>
              </div>
            )}
          </div>
        </div>
      );
    }

    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 p-8 text-center bg-gray-50/50">
        <div className="w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center mb-4 text-3xl">🍃</div>
        <h3 className="text-lg font-bold text-gray-600">Select Someone to Begin</h3>
        <p className="text-sm mt-2">Pick a child or teacher to view details.</p>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => setIsAuthenticated(true)} />;

  return (
    <>
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={handleLogout}
        onGoHome={() => navigateTo('DAILY_OPS')}
        canGoBack={navHistory.length > 1}
      />
      {toast && (
        <div className="fixed bottom-6 right-6 px-6 py-4 rounded-xl shadow-xl bg-gray-800 text-white font-bold z-50 animate-fade-in">
          {toast.message}
        </div>
      )}
      {/* Modal Analytics */}
      {isHealthAnalyticsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-gray-900/40 backdrop-blur-sm p-4" onClick={() => setIsHealthAnalyticsOpen(false)}>
           <div className="bg-white rounded-3xl shadow-2xl p-8 max-w-lg w-full" onClick={e => e.stopPropagation()}>
              <h2 className="text-2xl font-display font-bold mb-4">Center Health Pulse</h2>
              <div className="space-y-4">
                 <div className="p-4 bg-green-50 rounded-xl"><p className="text-xs text-green-600 uppercase font-bold">Today's Attendance</p><p className="text-2xl font-bold">{metrics.attendanceRate}% ({metrics.present}/{metrics.total})</p></div>
                 <div className="p-4 bg-blue-50 rounded-xl"><p className="text-xs text-blue-600 uppercase font-bold">Capacity Utilization</p><p className="text-2xl font-bold">88%</p></div>
              </div>
              <button onClick={() => setIsHealthAnalyticsOpen(false)} className="w-full mt-6 py-3 bg-primary-400 text-white font-bold rounded-xl">Close</button>
           </div>
        </div>
      )}
    </>
  );
};

export default App;

