                            <input type="text" value={editFormData.lastName} onChange={e => setEditFormData({...editFormData, lastName: e.target.value})} className="w-full p-2 border rounded-lg text-sm" />
                         </div>
                      </div>
                      <div className="space-y-1">
                         <label className="text-[10px] font-bold text-gray-400 uppercase">DOB</label>
                         <input type="date" value={editFormData.dob} onChange={e => setEditFormData({...editFormData, dob: e.target.value})} className="w-full p-2 border rounded-lg text-sm" />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[10px] font-bold text-gray-400 uppercase">Internal Notes</label>
                         <textarea rows={4} value={editFormData.notes} onChange={e => setEditFormData({...editFormData, notes: e.target.value})} className="w-full p-2 border rounded-lg text-sm" />
                      </div>
                      <div className="flex justify-end gap-2 pt-2">
                         <button onClick={() => setIsEditingProfile(false)} className="text-xs font-bold text-gray-400 px-2 py-1">Cancel</button>
                         <button onClick={handleUpdateChildProfile} className="text-xs font-bold bg-primary-400 text-white px-4 py-1.5 rounded-lg shadow-sm">Save Profile</button>
                      </div>
                   </div>
                 ) : (
                   <>
                     <div className="grid grid-cols-2 gap-4">
                        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                           <h4 className="text-[10px] font-bold text-gray-400 uppercase mb-1">Date of Birth</h4>
                           <p className="font-bold text-gray-800 text-sm">{selectedChild.dob || 'Not set'}</p>
                        </div>
                        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                           <h4 className="text-[10px] font-bold text-gray-400 uppercase mb-1">Age</h4>
                           <p className="font-bold text-gray-800 text-sm">{selectedChild.dob ? new Date().getFullYear() - new Date(selectedChild.dob).getFullYear() : '?'} Years</p>
                        </div>
                     </div>
                     <div className="bg-surface-50 p-5 rounded-2xl border border-gray-100">
                        <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Teacher Notes</h4>
                        <p className="text-sm text-gray-600 leading-relaxed italic">"{selectedChild.notes || 'No bio information available.'}"</p>
                     </div>
                   </>
                 )}
              </div>
            )}
          </div>
        </div>
      );
    }

    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 p-8 text-center bg-gray-50/50">
        <div className="w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center mb-4 text-3xl">🍃</div>
        <h3 className="text-lg font-bold text-gray-600">Select Someone to Begin</h3>
        <p className="text-sm mt-2">Pick a child or teacher to view details.</p>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={() => setIsAuthenticated(true)} />;

  return (
    <>
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={handleLogout}
        onGoHome={() => navigateTo('DAILY_OPS')}
        canGoBack={navHistory.length > 1}
      />
      {toast && (
        <div className={`fixed bottom-6 right-6 px-6 py-4 rounded-xl shadow-xl font-bold text-white z-50 animate-in slide-in-from-bottom-6 duration-300 ${toast.type === 'success' ? 'bg-gray-800' : 'bg-red-500'}`}>
          {toast.type === 'success' ? '✅' : '❌'} {toast.message}
        </div>
      )}
      {isHealthAnalyticsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-gray-900/40 backdrop-blur-sm p-4 animate-in fade-in" onClick={() => setIsHealthAnalyticsOpen(false)}>
           <div className="bg-white rounded-3xl shadow-2xl p-8 max-w-lg w-full animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-display font-bold text-gray-800">Center Health Pulse</h2>
                <button onClick={() => setIsHealthAnalyticsOpen(false)} className="text-gray-400 hover:text-gray-600">✕</button>
              </div>
              <div className="space-y-4">
                 <div className="p-5 bg-green-50 rounded-2xl border border-green-100">
                    <p className="text-xs text-green-600 uppercase font-bold tracking-wider mb-1">Current Attendance</p>
                    <p className="text-3xl font-display font-bold text-green-800">{metrics.attendanceRate}%</p>
                    <p className="text-sm text-green-600 font-medium mt-1">{metrics.present} children present / {metrics.total} total</p>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="p-4 bg-orange-50 rounded-2xl border border-orange-100">
                       <p className="text-[10px] text-orange-600 uppercase font-bold mb-1">Absence Alerts</p>
                       <p className="text-2xl font-bold text-orange-800">{metrics.absent}</p>
                    </div>
                    <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100">
                       <p className="text-[10px] text-blue-600 uppercase font-bold mb-1">Health Compliance</p>
                       <p className="text-2xl font-bold text-blue-800">92%</p>
                    </div>
                 </div>
              </div>
              <button onClick={() => setIsHealthAnalyticsOpen(false)} className="w-full mt-8 py-4 bg-primary-400 hover:bg-primary-500 text-white font-bold rounded-2xl shadow-lg transition-transform active:scale-95">Return to Dashboard</button>
           </div>
        </div>
      )}
    </>
  );
};

export default App;

