  const [navHistory, setNavHistory] = useState<AppSection[]>(['DAILY_OPS']);
  const [selectedCenterId, setSelectedCenterId] = useState<string>('c1');

  // Core Data State
  const [classrooms, setClassrooms] = useState<Classroom[]>(INITIAL_CLASSROOMS);
  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [staff, setStaff] = useState<StaffMember[]>(INITIAL_STAFF);
  const [activities, setActivities] = useState<Activity[]>(MOCK_ACTIVITIES);
  const [guardiansMap, setGuardiansMap] = useState<Record<string, Guardian[]>>(INITIAL_GUARDIANS);
  const [invoicesMap, setInvoicesMap] = useState<Record<string, Invoice[]>>(INITIAL_INVOICES);
  const [healthRecordsMap, setHealthRecordsMap] = useState<Record<string, HealthProfile>>(INITIAL_HEALTH_RECORDS);

  // Selection & UI State
  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('toddlers');
  const [selectedChildId, setSelectedChildId] = useState<string | null>('1');
  const [selectedStaffId, setSelectedStaffId] = useState<string | null>(null);
  const [activeChildTab, setActiveChildTab] = useState<ChildDetailTab>('TIMELINE');
  const [activeStaffTab, setActiveStaffTab] = useState<StaffDetailTab>('INFO');
  const [enrollmentTab, setEnrollmentTab] = useState<'PENDING' | 'WAITLIST'>('PENDING');

  // Form State
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isEditingStaff, setIsEditingStaff] = useState(false);
  const [isEditingHealth, setIsEditingHealth] = useState(false);
  const [isAddingGuardian, setIsAddingGuardian] = useState(false);
  const [isHealthAnalyticsOpen, setIsHealthAnalyticsOpen] = useState(false);
  const [loggingMedicationId, setLoggingMedicationId] = useState<string | null>(null);
  const [editFormData, setEditFormData] = useState<any>({});
  const [newGuardianData, setNewGuardianData] = useState({ name: '', relation: '', phone: '', email: '' });

  // Calculations
  const metrics = (() => {
    const total = children.filter(c => c.enrollmentStatus === 'ENROLLED').length;
    const present = children.filter(c => c.status === 'PRESENT' && c.enrollmentStatus === 'ENROLLED').length;
    return { 
      attendanceRate: total ? Math.round((present/total)*100) : 0,
      total,
      present,
      absent: total - present
    };
  })();

  const currentClassroom = classrooms.find(c => c.id === selectedClassroomId);
  const selectedChild = children.find(c => c.id === selectedChildId);
  const selectedStaff = staff.find(s => s.id === selectedStaffId);

  const filteredChildren = activeSection === 'ENROLLMENT' 
    ? children.filter(c => c.enrollmentStatus === enrollmentTab)
    : children.filter(c => c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED');

  const filteredStaff = activeSection === 'TEAM' ? staff : staff.filter(s => s.assignedClassroomIds.includes(selectedClassroomId));

  // Handlers
  const handleLogout = () => setIsAuthenticated(false);
  const navigateTo = (sec: AppSection) => {
    setActiveSection(sec);
    setNavHistory(prev => [...prev, sec]);
    setSelectedChildId(null);
    setSelectedStaffId(null);
  };

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Child Handlers
  const handleUpdateChildProfile = () => {
    if (!selectedChildId) return;
    setChildren(prev => prev.map(c => c.id === selectedChildId ? { ...c, ...editFormData } : c));
    setIsEditingProfile(false);
    showToast('Profile updated!');
  };

  const handleUpdateHealth = () => {
    if (!selectedChildId) return;
    setHealthRecordsMap(prev => ({
      ...prev,
      [selectedChildId]: { ...prev[selectedChildId], ...editFormData }
    }));
    setIsEditingHealth(false);
    showToast('Health records updated!');
  };

  const handleAddGuardian = () => {
    if (!selectedChildId || !newGuardianData.name) return;
    const newG: Guardian = {
      id: `g-${Date.now()}`,
      ...newGuardianData,
      avatarUrl: `https://api.dicebear.com/7.x/initials/svg?seed=${newGuardianData.name}`
    };
    setGuardiansMap(prev => ({
      ...prev,
      [selectedChildId]: [...(prev[selectedChildId] || []), newG]
    }));
    setIsAddingGuardian(false);
    setNewGuardianData({ name: '', relation: '', phone: '', email: '' });
    showToast('Guardian added');
  };

  const handleLogMedication = (medId: string, medName: string) => {
    if (!selectedChildId) return;
