                  <span>Enrollment</span>
                  <span className="bg-purple-100 text-purple-600 px-1.5 py-0.5 rounded text-[10px] font-bold">
                    {children.filter(c => c.enrollmentStatus === 'PENDING').length}
                  </span>
              </div>
              <div onClick={() => navigateTo('TEAM')} className={`flex items-center justify-between px-3 py-2 rounded-lg font-medium text-sm cursor-pointer ${activeSection === 'TEAM' ? 'bg-primary-100 text-primary-500 font-semibold shadow-sm' : 'text-gray-600 hover:bg-gray-50'}`}>
                  <span>Our Team</span>
              </div>
          </div>
      </div>

      {activeSection === 'DAILY_OPS' && (
        <div>
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 pl-2">Classrooms</h3>
            <div className="space-y-1">
            {classrooms.map(room => (
                <div key={room.id} onClick={() => { setSelectedClassroomId(room.id); setSelectedChildId(null); setSelectedStaffId(null); }} className={`flex items-center justify-between px-3 py-2 rounded-lg text-sm cursor-pointer transition-all ${room.id === selectedClassroomId ? 'bg-white border border-gray-100 shadow-sm text-gray-900 font-bold' : 'text-gray-600 hover:bg-gray-50 font-medium'}`}>
                    <span>{room.name}</span>
                    <span className="text-[10px] bg-gray-100 px-1.5 py-0.5 rounded text-gray-500">{room.enrolled}/{room.capacity}</span>
                </div>
            ))}
            </div>
        </div>
      )}

      <div onClick={() => setIsHealthAnalyticsOpen(true)} className="mt-8 p-4 bg-gray-50 rounded-xl border border-gray-100 cursor-pointer hover:bg-white hover:shadow-md transition-all group">
          <div className="flex justify-between items-start mb-2"><h4 className="text-xs font-bold text-gray-500">Center Attendance</h4></div>
          <div className="text-2xl font-display font-bold text-gray-800 group-hover:text-primary-500 transition-colors">{metrics.attendanceRate}%</div>
          <p className="text-[10px] text-gray-400">Click for full dashboard</p>
      </div>
    </div>
  );

  const ListPanelContent = () => (
    <div className="space-y-6">
      {activeSection === 'TEAM' ? (
        <div className="space-y-4">
           <h2 className="text-xl font-display font-bold text-gray-800">Staff Directory</h2>
           <div className="grid gap-3">
             {staff.map(s => (
               <div key={s.id} onClick={() => { setSelectedStaffId(s.id); setSelectedChildId(null); }} className={`p-4 bg-white rounded-nest border cursor-pointer transition-all hover:shadow-md flex items-center gap-4 ${selectedStaffId === s.id ? 'ring-2 ring-primary-300' : 'border-gray-100'}`}>
                 <img src={s.avatarUrl} className="w-12 h-12 rounded-full bg-primary-50" />
