               </div>
             ))}
           </div>
        </div>
      ) : activeSection === 'ENROLLMENT' ? (
        <div className="space-y-4">
            <div className="flex bg-gray-100 rounded-lg p-1">
                <button onClick={() => setEnrollmentTab('PENDING')} className={`flex-1 py-1.5 rounded-md text-xs font-bold transition-all ${enrollmentTab === 'PENDING' ? 'bg-white text-primary-600 shadow-sm' : 'text-gray-500'}`}>Pending</button>
                <button onClick={() => setEnrollmentTab('WAITLIST')} className={`flex-1 py-1.5 rounded-md text-xs font-bold transition-all ${enrollmentTab === 'WAITLIST' ? 'bg-white text-primary-600 shadow-sm' : 'text-gray-500'}`}>Waitlist</button>
            </div>
            {filteredChildren.map(child => (
