const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<{ role: UserRole, email: string } | null>(null);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [activeSection, setActiveSection] = useState<AppSection>('DAILY_OPS');
  const [navHistory, setNavHistory] = useState<AppSection[]>(['DAILY_OPS']);
  const [selectedCenterId, setSelectedCenterId] = useState<string>('c1');

  // Core Data State
  const [classrooms, setClassrooms] = useState<Classroom[]>(INITIAL_CLASSROOMS);
  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [staff, setStaff] = useState<StaffMember[]>(INITIAL_STAFF);
  const [activities, setActivities] = useState<Activity[]>(MOCK_ACTIVITIES);
  const [guardiansMap, setGuardiansMap] = useState<Record<string, Guardian[]>>(INITIAL_GUARDIANS);
  const [invoicesMap, setInvoicesMap] = useState<Record<string, Invoice[]>>(INITIAL_INVOICES);
  const [healthRecordsMap, setHealthRecordsMap] = useState<Record<string, HealthProfile>>(INITIAL_HEALTH_RECORDS);

  // Selection & UI State
  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('');
  const [selectedChildId, setSelectedChildId] = useState<string | null>(null);
  const [selectedStaffId, setSelectedStaffId] = useState<string | null>(null);
  const [activeChildTab, setActiveChildTab] = useState<ChildDetailTab>('TIMELINE');
  const [activeStaffTab, setActiveStaffTab] = useState<StaffDetailTab>('INFO');
  const [enrollmentTab, setEnrollmentTab] = useState<'PENDING' | 'WAITLIST'>('PENDING');

  // Form State
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isEditingStaff, setIsEditingStaff] = useState(false);
  const [isEditingHealth, setIsEditingHealth] = useState(false);
  const [isAddingGuardian, setIsAddingGuardian] = useState(false);
  const [isHealthAnalyticsOpen, setIsHealthAnalyticsOpen] = useState(false);
  const [loggingMedicationId, setLoggingMedicationId] = useState<string | null>(null);
  const [editFormData, setEditFormData] = useState<any>({});
  const [newGuardianData, setNewGuardianData] = useState({ name: '', relation: '', phone: '', email: '' });

  // Filter classrooms based on user role
  const teacherProfile = staff.find(s => s.email === currentUser?.email);
  const accessibleClassrooms = currentUser?.role === UserRole.ADMIN 
    ? classrooms 
    : classrooms.filter(c => teacherProfile?.assignedClassroomIds.includes(c.id));

  // Initialize selected classroom
  useEffect(() => {
    if (accessibleClassrooms.length > 0 && !selectedClassroomId) {
      setSelectedClassroomId(accessibleClassrooms[0].id);
    }
  }, [accessibleClassrooms, selectedClassroomId]);

  // Calculations
  const metrics = (() => {
    const relevantChildren = currentUser?.role === UserRole.ADMIN 
      ? children 
      : children.filter(c => teacherProfile?.assignedClassroomIds.includes(c.classroomId));

    const enrolledChildren = relevantChildren.filter(c => c.enrollmentStatus === 'ENROLLED');
    const total = enrolledChildren.length;
    const present = enrolledChildren.filter(c => c.status === 'PRESENT').length;
    return { 
      attendanceRate: total ? Math.round((present/total)*100) : 0,
      total,
      present,
      absent: total - present
    };
  })();

  const currentClassroom = classrooms.find(c => c.id === selectedClassroomId);
  const selectedChild = children.find(c => c.id === selectedChildId);
  const selectedStaff = staff.find(s => s.id === selectedStaffId);

  const filteredChildren = activeSection === 'ENROLLMENT' 
    ? children.filter(c => c.enrollmentStatus === enrollmentTab)
    : children.filter(c => c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED');

  const filteredStaff = activeSection === 'TEAM' ? staff : staff.filter(s => s.assignedClassroomIds.includes(selectedClassroomId));

  // Handlers
  const handleLogin = (role: UserRole, email: string) => {
    setCurrentUser({ role, email });
    setIsAuthenticated(true);
    // Reset to default room for the specific user
    const userProfile = staff.find(s => s.email === email);
    if (role === UserRole.TEACHER && userProfile?.assignedClassroomIds.length) {
      setSelectedClassroomId(userProfile.assignedClassroomIds[0]);
    } else {
      setSelectedClassroomId('toddlers');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setSelectedChildId(null);
    setSelectedStaffId(null);
  };

  const navigateTo = (sec: AppSection) => {
    setActiveSection(sec);
    setNavHistory(prev => [...prev, sec]);
    setSelectedChildId(null);
    setSelectedStaffId(null);
  };

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // Logic for updating data... (reusing existing logic)
  const handleUpdateChildProfile = () => {
    if (!selectedChildId) return;
    setChildren(prev => prev.map(c => c.id === selectedChildId ? { ...c, ...editFormData } : c));
    setIsEditingProfile(false);
    showToast('Profile updated!');
  };

  const handleUpdateHealth = () => {
    if (!selectedChildId) return;
    setHealthRecordsMap(prev => ({ ...prev, [selectedChildId]: { ...prev[selectedChildId], ...editFormData } }));
    setIsEditingHealth(false);
    showToast('Health records updated!');
  };

  const handleAddGuardian = () => {
    if (!selectedChildId || !newGuardianData.name) return;
    const newG: Guardian = { id: `g-${Date.now()}`, ...newGuardianData, avatarUrl: `https://api.dicebear.com/7.x/initials/svg?seed=${newGuardianData.name}` };
    setGuardiansMap(prev => ({ ...prev, [selectedChildId]: [...(prev[selectedChildId] || []), newG] }));
    setIsAddingGuardian(false);
    setNewGuardianData({ name: '', relation: '', phone: '', email: '' });
    showToast('Guardian added');
  };

  const handleLogMedication = (medId: string, medName: string) => {
    if (!selectedChildId) return;
    setLoggingMedicationId(medId);
    setTimeout(() => {
      const newAct: Activity = { id: `m-${Date.now()}`, childId: selectedChildId, type: ActivityType.MEDICATION, title: 'Medication Logged', description: `Administered dose of ${medName}`, timestamp: new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }), authorName: currentUser?.role === UserRole.TEACHER ? (teacherProfile?.name || 'Teacher') : 'Manager' };
      setActivities(prev => [newAct, ...prev]);
      setLoggingMedicationId(null);
      showToast('Dose recorded');
    }, 800);
  };

  const handlePayInvoice = (invoiceId: string) => {
    if (!selectedChildId) return;
    setInvoicesMap(prev => ({ ...prev, [selectedChildId]: prev[selectedChildId].map(inv => inv.id === invoiceId ? { ...inv, status: 'PAID' } : inv) }));
    showToast('Payment successful!');
  };

  const handleSaveStaff = () => {
    setStaff(prev => prev.map(s => s.id === selectedStaffId ? { ...s, ...editFormData } : s));
    setIsEditingStaff(false);
    showToast('Staff profile saved');
  };

  // --- Layout Sub-Components ---

