// --- APP COMPONENT ---

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<{ role: UserRole, email: string } | null>(null);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [activeSection, setActiveSection] = useState<AppSection>('DAILY_OPS');
  const [selectedCenterId, setSelectedCenterId] = useState<string>('c1');

  // Core Data State
  const [classrooms, setClassrooms] = useState<Classroom[]>(INITIAL_CLASSROOMS);
  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [staff, setStaff] = useState<StaffMember[]>(INITIAL_STAFF);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [guardiansMap, setGuardiansMap] = useState<Record<string, Guardian[]>>(INITIAL_GUARDIANS);
  const [notificationLogs, setNotificationLogs] = useState<NotificationLog[]>([]);

  // Selection & UI State
  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('');
  const [selectedChildId, setSelectedChildId] = useState<string | null>(null);
  const [selectedStaffId, setSelectedStaffId] = useState<string | null>(null);
  const [activeChildTab, setActiveChildTab] = useState<ChildDetailTab>('TIMELINE');
  const [activeStaffTab, setActiveStaffTab] = useState<StaffDetailTab>('INFO');
  const [enrollmentTab, setEnrollmentTab] = useState<'PENDING' | 'WAITLIST'>('PENDING');

  const teacherProfile = useMemo(() => staff.find(s => s.email === currentUser?.email), [staff, currentUser]);
  const accessibleClassrooms = useMemo(() => 
    currentUser?.role === UserRole.ADMIN ? classrooms : classrooms.filter(c => teacherProfile?.assignedClassroomIds.includes(c.id)),
    [currentUser, classrooms, teacherProfile]
  );

  useEffect(() => {
    if (accessibleClassrooms.length > 0 && !selectedClassroomId) {
      setSelectedClassroomId(accessibleClassrooms[0].id);
    }
  }, [accessibleClassrooms, selectedClassroomId]);

  // --- AUTOMATION ENGINE ---

  const triggerWaitlistNotifications = (classroomId: string, updatedClassrooms: Classroom[], updatedChildren: Child[]) => {
    const room = updatedClassrooms.find(r => r.id === classroomId);
    if (!room) return;

    const availableSpots = room.capacity - room.enrolled;
    if (availableSpots <= 0) return;

    // Find children on waitlist for this specific room
    const waitlisted = updatedChildren.filter(c => c.classroomId === classroomId && c.enrollmentStatus === 'WAITLIST');
    const toNotify = waitlisted.slice(0, availableSpots);

    const newLogs: NotificationLog[] = [];
    toNotify.forEach(child => {
      const guardians = guardiansMap[child.id] || [];
      guardians.forEach(g => {
        newLogs.push({
          id: `log-${Date.now()}-${Math.random()}`,
          type: g.email ? 'EMAIL' : 'SMS',
          recipient: g.email || g.phone,
          subject: `A spot has opened for ${child.firstName}!`,
          timestamp: new Date().toLocaleTimeString(),
          status: 'SENT'
        });
      });
    });

    if (newLogs.length > 0) {
      setNotificationLogs(prev => [...newLogs, ...prev]);
      showToast(`Automatically notified ${toNotify.length} families about openings!`);
    }
  };

  const handleUpdateCapacity = (classroomId: string, newCapacity: number) => {
    const updatedClassrooms = classrooms.map(c => c.id === classroomId ? { ...c, capacity: newCapacity } : c);
    setClassrooms(updatedClassrooms);
    showToast(`Updated capacity for ${classrooms.find(r => r.id === classroomId)?.name}`);

    // Check if waitlist needs notification
    triggerWaitlistNotifications(classroomId, updatedClassrooms, children);
  };

  const handleEnrollChild = (childId: string) => {
    const child = children.find(c => c.id === childId);
    if (!child) return;

    const targetRoom = classrooms.find(r => r.id === child.classroomId);
    if (targetRoom && targetRoom.enrolled >= targetRoom.capacity) {
      showToast('Classroom is at full capacity!', 'error');
      return;
    }

    const updatedChildren = children.map(c => c.id === childId ? { ...c, enrollmentStatus: 'ENROLLED' as EnrollmentStatus, status: 'PRESENT' as const } : c);
    const updatedClassrooms = classrooms.map(r => r.id === child.classroomId ? { ...r, enrolled: r.enrolled + 1 } : r);

    setChildren(updatedChildren);
