            </button>
          )}
          <button onClick={() => setActiveSection('TEAM')} className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'TEAM' ? 'bg-primary-100 text-primary-600' : 'text-gray-600'}`}>👥 Staff</button>
