                   <span className="text-[10px] font-bold bg-primary-50 text-primary-600 px-2 py-0.5 rounded uppercase">{log.type}</span>
                   <span className="text-[10px] text-gray-400 font-bold">{log.timestamp}</span>
                </div>
                <p className="text-sm font-bold text-gray-800">{log.recipient}</p>
                <p className="text-xs text-gray-500">{log.subject}</p>
             </div>
           )) : <p className="text-center py-12 text-gray-400 text-sm">No notification logs yet.</p>}
        </div>
      </div>
    );

    if (activeSection === 'CLASSROOM_SETTINGS') return (
