export enum UserRole {
  ADMIN = 'ADMIN',
  TEACHER = 'TEACHER',
  PARENT = 'PARENT'
}

export enum ActivityType {
  CHECK_IN = 'CHECK_IN',
  CHECK_OUT = 'CHECK_OUT',
  PHOTO = 'PHOTO',
  MEAL = 'MEAL',
  NAP = 'NAP',
  INCIDENT = 'INCIDENT',
  NOTE = 'NOTE',
  MEDICATION = 'MEDICATION'
}

