  title: string;
  description?: string;
  mediaUrl?: string;
  timestamp: string;
  authorName: string;
}

export interface StaffMember {
  id: string;
  name: string;
  role: string; // e.g. "Lead Teacher", "Assistant"
  email: string;
  phone: string;
  avatarUrl: string;
  bio?: string;
  joinedDate: string;
  assignedClassroomIds: string[];
}

