export interface Medication {
  id: string;
  name: string;
  dosage: string;
  frequency: string;
  instructions?: string;
  lastAdministered?: string;
  endDate?: string;
}

export interface HealthProfile {
  childId: string;
  bloodType?: string;
  doctorName?: string;
  doctorPhone?: string;
  immunizations: Immunization[];
  medications: Medication[];
  specialNeeds?: string;
}

