}

// --- HEALTH MODULE TYPES ---

export interface Immunization {
  id: string;
  name: string;
  dueDate: string;
  dateGiven?: string;
  status: 'COMPLIANT' | 'OVERDUE' | 'UPCOMING';
}

export interface Medication {
  id: string;
