          </section>
          <section className="space-y-4">
            <h4 className="text-[10px] font-bold text-gray-400 uppercase">Weekly Schedule</h4>
            {selectedLessonPlan.activities.map((a, i) => (
              <div key={i} className="pl-4 border-l-2 border-primary-100"><p className="text-xs font-bold text-primary-400 uppercase">{a.day}: {a.activityName}</p><p className="text-[10px] text-gray-500 mt-1">{a.description}</p></div>
            ))}
          </section>
        </div>
      );
    }

    if (selectedChild) {
      const health = healthMap[selectedChild.id];
      const childForms = CONSENT_TEMPLATES.map(t => ({ template: t, signed: signedForms.find(f => f.childId === selectedChild.id && f.templateId === t.id) }));
      return (
        <div className="flex flex-col h-full bg-white overflow-hidden">
          <div className="h-40 bg-primary-100 shrink-0 relative flex items-end p-6 gap-4">
            <div className="relative">
              <img src={selectedChild.avatarUrl} className="w-20 h-20 rounded-full border-4 border-white shadow-xl bg-white object-cover" />
              <button onClick={() => fileInputRef.current?.click()} className="absolute bottom-0 right-0 w-8 h-8 bg-white rounded-full border border-gray-100 shadow-lg flex items-center justify-center text-xs">📸</button>
            </div>
            <div className="mb-4"><h2 className="text-2xl font-bold text-gray-800 leading-tight">{selectedChild.firstName} {selectedChild.lastName}</h2><p className="text-[10px] text-gray-500 font-bold uppercase">{selectedChild.classroom}</p></div>
          </div>
          <div className="flex-1 overflow-y-auto p-8 space-y-8">
            {activeChildTab === 'HEALTH' ? (
              <div className="space-y-6">
                <h3 className="text-[10px] font-bold text-gray-400 uppercase">Medical Summary</h3>
                <div className="bg-red-50 p-4 rounded-2xl border border-red-100"><p className="text-[10px] font-bold text-red-400 uppercase mb-1">Warnings</p><p className="text-sm font-bold text-red-700">{health?.specialNeeds || 'None'}</p></div>
                <div className="bg-surface-50 p-4 rounded-2xl border border-gray-100"><p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Doctor</p><p className="text-sm font-bold text-gray-700">{health?.doctorName || 'Not Assigned'}</p></div>
              </div>
            ) : activeChildTab === 'FORMS' ? (
              <div className="space-y-4">
                <h3 className="text-[10px] font-bold text-gray-400 uppercase">Documents</h3>
                {childForms.map(({ template, signed }) => (
                  <div key={template.id} className={`p-4 rounded-2xl border ${signed?.status === 'SIGNED' ? 'bg-white border-gray-100 opacity-60' : 'bg-primary-50 border-primary-100'}`}>
                    <div className="flex justify-between items-center"><h4 className="text-xs font-bold text-gray-800">{template.title}</h4>{signed?.status === 'SIGNED' ? <span className="text-[9px] font-bold text-green-500">✅ COMPLETED</span> : <button onClick={() => setSigningForm(template)} className="text-[9px] font-bold bg-primary-400 text-white px-2 py-1 rounded-full">SIGN NOW</button>}</div>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-center text-gray-400 text-sm mt-12">Feed activities loading...</p>
            )}
          </div>
        </div>
      );
    }

    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 p-8 text-center bg-gray-50/50">
        <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-6 text-2xl shadow-inner">Nest</div>
        <h3 className="text-lg font-bold text-gray-600">Select an item</h3>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); }} />;

  return (
    <>
      <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setSelectedChildId(null); setActiveSection('DAILY_OPS'); }}
        onGoHome={() => setActiveSection('DAILY_OPS')}
      />
      {signingForm && (
        <div className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6 animate-in fade-in">
          <div className="bg-white rounded-[32px] w-full max-w-lg shadow-2xl p-8 space-y-6">
            <div className="flex justify-between items-start"><h3 className="text-2xl font-bold text-gray-800">{signingForm.title}</h3><button onClick={() => setSigningForm(null)} className="text-gray-300 text-2xl">×</button></div>
            <div className="p-6 bg-surface-50 rounded-2xl border border-gray-100 text-sm text-gray-600 font-medium">{signingForm.content}</div>
            <button onClick={() => {
              const newSignedForm: SignedConsentForm = { id: `f-${Date.now()}`, childId: selectedChildId!, templateId: signingForm.id, status: 'SIGNED', signedAt: new Date().toISOString().split('T')[0], signerName: 'Guardian' };
              setSignedForms([...signedForms, newSignedForm]);
              setSigningForm(null);
              showToast('Form Signed!');
            }} className="w-full py-4 bg-primary-400 text-white font-bold text-lg rounded-2xl shadow-xl shadow-primary-200">Submit Digital Signature</button>
          </div>
        </div>
      )}
      {toast && <div className={`fixed bottom-8 right-8 px-6 py-4 rounded-2xl shadow-2xl font-bold text-white z-50 animate-in slide-in-from-bottom-8 ${toast.type === 'success' ? 'bg-gray-900/90' : 'bg-red-500'}`}>{toast.message}</div>}
    </>
  );
};

