  const [activeSection, setActiveSection] = useState<AppSection>('DAILY_OPS');

  const [classrooms] = useState<Classroom[]>(INITIAL_CLASSROOMS);
  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [staff, setStaff] = useState<StaffMember[]>(INITIAL_STAFF);
  const [shifts, setShifts] = useState<ShiftAssignment[]>(INITIAL_SHIFTS);
  const [lessonPlans, setLessonPlans] = useState<LessonPlan[]>(INITIAL_LESSON_PLANS);
  const [signedForms, setSignedForms] = useState<SignedConsentForm[]>(INITIAL_SIGNED_FORMS);
  const [guardiansMap] = useState<Record<string, Guardian[]>>(INITIAL_GUARDIANS);
  const [healthMap] = useState<Record<string, HealthProfile>>(INITIAL_HEALTH_PROFILES);
  const [leads] = useState(INITIAL_LEADS);

  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('');
  const [selectedChildId, setSelectedChildId] = useState<string | null>(null);
  const [selectedStaffId, setSelectedStaffId] = useState<string | null>(null);
  const [selectedLessonPlanId, setSelectedLessonPlanId] = useState<string | null>(null);
  const [activeChildTab, setActiveChildTab] = useState<ChildDetailTab>('TIMELINE');

  const [signingForm, setSigningForm] = useState<ConsentTemplate | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const teacherProfile = useMemo(() => staff.find(s => s.email === currentUser?.email), [staff, currentUser]);
  const myChildren = useMemo(() => {
    if (currentUser?.role !== UserRole.PARENT) return [];
    return children.filter(c => (guardiansMap[c.id] || []).some(g => g.email === currentUser.email));
  }, [children, currentUser, guardiansMap]);

  const selectedChild = useMemo(() => children.find(c => c.id === selectedChildId), [children, selectedChildId]);
  const selectedStaff = useMemo(() => staff.find(s => s.id === selectedStaffId), [staff, selectedStaffId]);
  const selectedLessonPlan = useMemo(() => lessonPlans.find(lp => lp.id === selectedLessonPlanId), [lessonPlans, selectedLessonPlanId]);

  const centerHealth = useMemo(() => {
    const totalEnrolled = children.filter(c => c.enrollmentStatus === 'ENROLLED').length;
    const totalCapacity = classrooms.reduce((acc, c) => acc + c.capacity, 0);
    const occupancyRate = totalCapacity > 0 ? Math.round((totalEnrolled / totalCapacity) * 100) : 0;
    const arTotal = 4250;
    const ratios = classrooms.map(room => {
      const roomChildren = children.filter(c => c.classroomId === room.id && c.status === 'PRESENT');
      const roomStaff = staff.filter(s => s.assignedClassroomIds.includes(room.id));
      const ratioValue = roomStaff.length > 0 ? `${roomChildren.length}:${roomStaff.length}` : 'N/A';
      return { name: room.name, ratio: ratioValue, compliant: roomStaff.length > 0 && (roomChildren.length / roomStaff.length) <= 10 };
    });
    return { totalEnrolled, totalCapacity, occupancyRate, arTotal, ratios };
  }, [children, classrooms, staff]);

  useEffect(() => {
    if (currentUser?.role === UserRole.PARENT && myChildren.length > 0) setSelectedChildId(myChildren[0].id);
  }, [currentUser, myChildren]);

  useEffect(() => {
    const accessible = currentUser?.role === UserRole.ADMIN ? classrooms : classrooms.filter(c => teacherProfile?.assignedClassroomIds.includes(c.id));
    if (currentUser?.role !== UserRole.PARENT && accessible.length > 0 && !selectedClassroomId) {
      setSelectedClassroomId(accessible[0].id);
    }
  }, [classrooms, teacherProfile, currentUser, selectedClassroomId]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleToggleShift = (staffId: string, day: string) => {
    const types: ShiftType[] = ['OPEN', 'MID', 'CLOSE', 'OFF'];
    const existing = shifts.find(s => s.staffId === staffId && s.day === day);
    let nextType: ShiftType = 'OPEN';
    if (existing) {
      const idx = types.indexOf(existing.type);
      nextType = types[(idx + 1) % types.length];
    }
    setShifts(prev => {
      const filtered = prev.filter(s => !(s.staffId === staffId && s.day === day));
      return nextType === 'OFF' ? filtered : [...filtered, { staffId, day, type: nextType }];
    });
    showToast(`Shift updated for ${day}`);
  };

  // Fix: Added the missing handleFileChange function used by the hidden file input
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      showToast(`Uploading ${file.name}...`);
      // Simulated upload delay
      setTimeout(() => {
        showToast('File uploaded successfully!');
      }, 1500);
    }
  };

  const SidebarContent = () => (
    <div className="space-y-6">
      <div className="space-y-1">
