            <button onClick={() => { setActiveSection('PARENT_HEALTH'); setActiveChildTab('HEALTH'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'PARENT_HEALTH' ? 'bg-primary-100 text-primary-600 shadow-sm' : 'text-gray-600 hover:bg-gray-50'}`}>🏥 Medical Log</button>
            <button onClick={() => { setActiveSection('CONSENT_FORMS'); setActiveChildTab('FORMS'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'CONSENT_FORMS' ? 'bg-primary-100 text-primary-600 shadow-sm' : 'text-gray-600 hover:bg-gray-50'}`}>📜 Consent Forms</button>
          </>
        ) : (
          <>
            {currentUser?.role === UserRole.ADMIN && (
              <>
                <button onClick={() => setActiveSection('CRM_DASHBOARD')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'CRM_DASHBOARD' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>📊 CRM Health</button>
                <button onClick={() => setActiveSection('STAFF_SCHEDULE')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'STAFF_SCHEDULE' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🗓️ Schedule</button>
              </>
            )}
            <button onClick={() => setActiveSection('LESSON_PLANS')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'LESSON_PLANS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🍎 Lesson Plans</button>
          </>
        )}
      </div>
      {currentUser?.role !== UserRole.PARENT && (
