        <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-6 text-2xl shadow-inner">Nest</div>
        <h3 className="text-lg font-bold text-gray-600">Select an item</h3>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); }} />;

  return (
    <>
      <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setSelectedChildId(null); setActiveSection('DAILY_OPS'); }}
        onGoHome={() => setActiveSection('DAILY_OPS')}
      />
      {signingForm && (
        <div className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6 animate-in fade-in">
          <div className="bg-white rounded-[32px] w-full max-w-lg shadow-2xl p-8 space-y-6">
            <div className="flex justify-between items-start"><h3 className="text-2xl font-bold text-gray-800">{signingForm.title}</h3><button onClick={() => setSigningForm(null)} className="text-gray-300 text-2xl">×</button></div>
            <div className="p-6 bg-surface-50 rounded-2xl border border-gray-100 text-sm text-gray-600 font-medium">{signingForm.content}</div>
            <button onClick={() => {
              const newSignedForm: SignedConsentForm = { id: `f-${Date.now()}`, childId: selectedChildId!, templateId: signingForm.id, status: 'SIGNED', signedAt: new Date().toISOString().split('T')[0], signerName: 'Guardian' };
              setSignedForms([...signedForms, newSignedForm]);
              setSigningForm(null);
              showToast('Form Signed!');
            }} className="w-full py-4 bg-primary-400 text-white font-bold text-lg rounded-2xl shadow-xl shadow-primary-200">Submit Digital Signature</button>
          </div>
        </div>
      )}
      {toast && <div className={`fixed bottom-8 right-8 px-6 py-4 rounded-2xl shadow-2xl font-bold text-white z-50 animate-in slide-in-from-bottom-8 ${toast.type === 'success' ? 'bg-gray-900/90' : 'bg-red-500'}`}>{toast.message}</div>}
    </>
  );
};

