  }, [children]);

  // --- ACTIONS ---
  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const navigateTo = (section: AppSection) => {
    setActiveSection(section);
    setNavStack(prev => [...prev, section]);
  };

  const goBack = () => {
    if (navStack.length > 1) {
      const newStack = [...navStack];
      newStack.pop();
      setNavStack(newStack);
      setActiveSection(newStack[newStack.length - 1]);
    }
  };

  const handleCheckInAll = () => {
    setChildren(prev => prev.map(c => 
      c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED' 
        ? { ...c, status: 'PRESENT', lastActivityTime: 'Just now' } 
        : c
    ));
    showToast(`Checked in all children in ${selectedClassroomId}`);
  };

  const handleQuickAdd = () => {
    showToast("Quick Add modal triggered", "success");
  };

  const handleToggleShift = (staffId: string, day: string) => {
    const existing = shifts.find(s => s.staffId === staffId && s.day === day);
    const nextType = SHIFT_TYPES[(SHIFT_TYPES.indexOf(existing?.type || 'OFF') + 1) % SHIFT_TYPES.length];
    setShifts(prev => {
      const filtered = prev.filter(s => !(s.staffId === staffId && s.day === day));
      return nextType === 'OFF' ? filtered : [...filtered, { staffId, day, type: nextType }];
    });
  };

  const handleLeadStatusChange = (leadId: string) => {
    const statuses = ['Inquiry', 'Tour Scheduled', 'Waitlist'];
    setLeads(prev => prev.map(l => {
      if (l.id === leadId) {
        const next = statuses[(statuses.indexOf(l.status) + 1) % statuses.length];
        return { ...l, status: next };
      }
      return l;
    }));
    showToast("Lead status advanced");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && selectedChildId) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const base64 = ev.target?.result as string;
        setChildren(prev => prev.map(c => c.id === selectedChildId ? { ...c, avatarUrl: base64 } : c));
        showToast("Profile picture updated!");
      };
      reader.readAsDataURL(file);
    }
  };

  // --- RENDER HELPERS ---

  const SidebarContent = () => (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3 pl-2">
          {currentUser?.role === UserRole.PARENT ? 'Leo\'s Portal' : 'Main Hub'}
        </h3>
        {currentUser?.role === UserRole.PARENT ? (
          <>
            <button onClick={() => { navigateTo('DAILY_OPS'); setActiveChildTab('TIMELINE'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'DAILY_OPS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600'}`}>🏠 Daily Feed</button>
            <button onClick={() => { navigateTo('PARENT_HEALTH'); setActiveChildTab('HEALTH'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'PARENT_HEALTH' ? 'bg-primary-100 text-primary-600' : 'text-gray-600'}`}>🏥 Health Log</button>
            <button onClick={() => { navigateTo('CONSENT_FORMS'); setActiveChildTab('FORMS'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'CONSENT_FORMS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600'}`}>📜 Consent Forms</button>
          </>
        ) : (
          <>
            {currentUser?.role === UserRole.ADMIN && (
              <>
                <button onClick={() => navigateTo('CRM_DASHBOARD')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'CRM_DASHBOARD' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>📊 CRM Dashboard</button>
                <button onClick={() => navigateTo('STAFF_SCHEDULE')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'STAFF_SCHEDULE' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🗓️ Staff Schedule</button>
              </>
            )}
            <button onClick={() => navigateTo('LESSON_PLANS')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'LESSON_PLANS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🍎 Lesson Plans</button>
            <button onClick={() => navigateTo('DAILY_OPS')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'DAILY_OPS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🏠 Live Feed</button>
            <button onClick={() => navigateTo('STUDENTS')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'STUDENTS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>👶 Students</button>
          </>
        )}
      </div>
    </div>
  );

  const ListPanelContent = () => {
    switch (activeSection) {
      case 'CRM_DASHBOARD':
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-left-4">
            <h2 className="text-xl font-bold text-gray-800">Pipeline</h2>
            {['Inquiry', 'Tour Scheduled', 'Waitlist'].map(st => (
              <div key={st} className="p-4 bg-white border border-gray-100 rounded-nest">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">{st}</p>
                <div className="space-y-2">
                  {leads.filter(l => l.status === st).map(l => (
                    <div key={l.id} onClick={() => handleLeadStatusChange(l.id)} className="p-3 bg-surface-50 rounded-xl border border-gray-100 flex justify-between items-center cursor-pointer hover:border-primary-200 transition-colors group">
                      <div>
                        <p className="text-sm font-bold text-gray-700">{l.childName}</p>
                        <p className="text-[10px] text-gray-400">{l.parentName}</p>
                      </div>
                      <span className="text-[10px] text-primary-300 group-hover:text-primary-500 font-bold transition-colors">Move →</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        );
      case 'STAFF_SCHEDULE':
        return (
          <div className="space-y-6 animate-in fade-in">
            <h2 className="text-xl font-bold text-gray-800">Coverage</h2>
            <div className="bg-white rounded-nest border border-gray-100 overflow-x-auto shadow-sm p-4">
              <table className="w-full text-left text-[11px]">
                <thead className="border-b border-gray-50">
                  <tr>
                    <th className="pb-3 text-gray-400 uppercase font-bold tracking-widest">Teacher</th>
                    {DAYS.map(d => <th key={d} className="pb-3 text-center text-gray-400 uppercase font-bold">{d}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {INITIAL_STAFF.map(s => (
                    <tr key={s.id} className="group">
                      <td className="py-4 font-bold text-gray-700">{s.name.split(' ')[0]}</td>
                      {DAYS.map(d => {
                        const sh = shifts.find(x => x.staffId === s.id && x.day === d);
                        return (
                          <td key={d} className="py-2 text-center">
                            <button 
                              onClick={() => handleToggleShift(s.id, d)}
                              className={`w-10 h-6 rounded-full text-[8px] font-black border transition-all ${
                                sh?.type === 'OPEN' ? 'bg-green-50 border-green-200 text-green-600' :
                                sh?.type === 'MID' ? 'bg-blue-50 border-blue-200 text-blue-600' :
                                sh?.type === 'CLOSE' ? 'bg-orange-50 border-orange-200 text-orange-600' :
                                'bg-gray-50 border-gray-100 text-gray-300'
                              }`}
                            >
                              {sh?.type || 'OFF'}
                            </button>
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      case 'LESSON_PLANS':
        return (
          <div className="space-y-4">
            <h2 className="text-xl font-bold text-gray-800">Curriculum</h2>
            {lessonPlans.map(lp => (
              <div key={lp.id} onClick={() => setSelectedLessonPlanId(lp.id)} className={`p-5 rounded-nest border transition-all cursor-pointer ${selectedLessonPlanId === lp.id ? 'bg-white border-primary-300 shadow-md ring-2 ring-primary-50' : 'bg-white border-gray-100'}`}>
                <div className="flex justify-between items-center mb-1">
                  <h4 className="font-bold text-gray-800">{lp.title}</h4>
                  <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${lp.status === 'PUBLISHED' ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'}`}>{lp.status}</span>
                </div>
                <p className="text-xs text-gray-400">Theme: {lp.theme}</p>
              </div>
            ))}
          </div>
        );
      default:
        const listChildren = currentUser?.role === UserRole.PARENT ? myChildren : children.filter(c => c.classroomId === selectedClassroomId);
        return (
          <div className="space-y-4">
            <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Roster</h3>
            {listChildren.map(c => (
              <NestCard key={c.id} child={c} selected={selectedChildId === c.id} onClick={() => setSelectedChildId(c.id)} />
            ))}
          </div>
        );
    }
  };

  const DetailPanelContent = () => {
    if (activeSection === 'CRM_DASHBOARD') {
      return (
        <div className="flex flex-col h-full bg-white p-8 space-y-10 overflow-y-auto animate-in slide-in-from-right-4">
          <div>
            <h3 className="text-2xl font-bold text-gray-800">Operations</h3>
            <p className="text-xs text-primary-400 font-bold uppercase mt-1">Real-time health</p>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-primary-50 p-6 rounded-[32px] border border-primary-100">
              <p className="text-[10px] font-bold text-primary-400 uppercase tracking-widest mb-1">Occupancy</p>
              <p className="text-3xl font-bold text-primary-600">{centerHealth.occupancy}%</p>
              <div className="w-full bg-white h-1 rounded-full mt-3 overflow-hidden">
                <div className="bg-primary-300 h-full" style={{ width: `${centerHealth.occupancy}%` }} />
