              </div>
            ))}
          </div>
        </div>
      );
    }

    if (selectedLessonPlan && activeSection === 'LESSON_PLANS') {
      return (
        <div className="flex flex-col h-full bg-white p-8 overflow-y-auto animate-in slide-in-from-right-4">
          <h3 className="text-2xl font-bold text-gray-800 mb-6">{selectedLessonPlan.title}</h3>
          <div className="space-y-6">
            <section className="p-5 bg-surface-50 rounded-3xl border border-gray-100">
              <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">Objectives</h4>
              {selectedLessonPlan.objectives.map((o, i) => <div key={i} className="text-xs text-gray-700 font-medium mb-2">✨ {o}</div>)}
            </section>
            <section className="space-y-4">
              <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Weekly Flow</h4>
              {selectedLessonPlan.activities.map(a => (
                <div key={a.day} className="pl-4 border-l-2 border-primary-100">
                  <p className="text-xs font-bold text-primary-400 uppercase">{a.day}: {a.activityName}</p>
                  <p className="text-[10px] text-gray-400 mt-1">{a.description}</p>
                </div>
              ))}
            </section>
          </div>
        </div>
      );
    }

    if (selectedChild) {
      const childActivities = activities.filter(a => a.childId === selectedChild.id);
      return (
        <div className="flex flex-col h-full bg-white overflow-hidden">
          <div className="h-40 bg-primary-100 flex items-end p-6 gap-4 relative">
            <div className="relative group">
              <img src={selectedChild.avatarUrl} className="w-20 h-20 rounded-full border-4 border-white shadow-xl bg-white object-cover" />
              <button onClick={() => fileInputRef.current?.click()} className="absolute -bottom-1 -right-1 w-8 h-8 bg-white rounded-full border border-gray-100 shadow-md flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">📸</button>
            </div>
            <div className="mb-4">
              <h2 className="text-2xl font-bold text-gray-800 leading-tight">{selectedChild.firstName} {selectedChild.lastName}</h2>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">{selectedChild.classroom}</p>
            </div>
          </div>
          <div className="flex border-b border-gray-100 px-6 gap-6">
            {['TIMELINE', 'HEALTH', 'FORMS'].map(tab => (
              <button 
                key={tab} 
                onClick={() => setActiveChildTab(tab as any)}
                className={`py-4 text-[10px] font-bold relative transition-colors ${activeChildTab === tab ? 'text-primary-500' : 'text-gray-400'}`}
              >
                {tab}
                {activeChildTab === tab && <div className="absolute bottom-0 left-0 right-0 h-1 bg-primary-300 rounded-t-full" />}
              </button>
            ))}
          </div>
          <div className="flex-1 overflow-y-auto p-8 bg-surface-50/30">
            {activeChildTab === 'TIMELINE' ? (
              childActivities.length > 0 ? childActivities.map(act => <ActivityFeedItem key={act.id} activity={act} />) : <p className="text-center text-gray-400 text-xs mt-10">No activities recorded today.</p>
            ) : activeChildTab === 'HEALTH' ? (
              <div className="space-y-6">
                <div className="bg-red-50 p-4 rounded-2xl border border-red-100"><p className="text-[10px] font-bold text-red-400 uppercase tracking-widest mb-1">Critical Allergy</p><p className="text-sm font-bold text-red-800">Peanuts - EpiPen in Classroom Bag 1A</p></div>
                <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm"><p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Doctor</p><p className="text-sm font-bold text-gray-700">Dr. Sarah Miller (555-0912)</p></div>
              </div>
            ) : (
              <div className="space-y-3">
                {CONSENT_TEMPLATES.map(t => {
                  const isSigned = signedForms.some(f => f.childId === selectedChild.id && f.templateId === t.id);
                  return (
                    <div key={t.id} className={`p-4 rounded-2xl border flex justify-between items-center ${isSigned ? 'bg-white border-gray-100' : 'bg-primary-50 border-primary-200'}`}>
                      <div><p className="text-xs font-bold text-gray-800">{t.title}</p><p className="text-[9px] text-gray-400 uppercase font-black">{isSigned ? 'Compliant' : 'Missing Signature'}</p></div>
                      {!isSigned && <button onClick={() => setSigningForm(t)} className="text-[9px] font-bold bg-primary-400 text-white px-2 py-1 rounded-full">Sign</button>}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      );
    }

    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 p-8 text-center bg-gray-50/50">
        <div className="w-20 h-20 bg-white rounded-blob flex items-center justify-center mb-6 text-2xl shadow-inner">🌱</div>
        <h3 className="text-lg font-bold text-gray-600">Select an item</h3>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); }} />;

  return (
    <>
      <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setSelectedChildId(null); setActiveSection('DAILY_OPS'); setNavStack(['DAILY_OPS']); }}
        onGoHome={() => { setActiveSection('DAILY_OPS'); setNavStack(['DAILY_OPS']); }}
        onGoBack={goBack}
        canGoBack={navStack.length > 1}
        onCheckIn={handleCheckInAll}
        onQuickAdd={handleQuickAdd}
      />
      {signingForm && (
        <div className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6 animate-in zoom-in duration-200">
          <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl p-10 space-y-8">
            <h3 className="text-3xl font-bold text-gray-800">{signingForm.title}</h3>
            <p className="text-sm text-gray-600 leading-relaxed font-medium bg-surface-50 p-6 rounded-3xl border border-gray-100">{signingForm.content}</p>
            <button 
              onClick={() => {
                setSignedForms(prev => [...prev, { id: `sf-${Date.now()}`, childId: selectedChildId!, templateId: signingForm.id, status: 'SIGNED', signedAt: new Date().toLocaleDateString(), signerName: 'Guardian' }]);
                setSigningForm(null);
                showToast("Document signed successfully!");
              }} 
              className="w-full py-5 bg-primary-400 text-white font-bold text-lg rounded-[24px] shadow-xl"
            >
              Sign & Approve
            </button>
          </div>
        </div>
      )}
      {toast && (
        <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 px-6 py-4 rounded-2xl shadow-2xl font-bold text-white z-[110] animate-in slide-in-from-bottom-8 ${toast.type === 'success' ? 'bg-gray-900/90' : 'bg-red-500'}`}>
          {toast.message}
        </div>
      )}
    </>
  );
};

export default App;

