type AppSection = 'DAILY_OPS' | 'STUDENTS' | 'TEAM' | 'CONSENT_FORMS' | 'CRM_DASHBOARD' | 'STAFF_SCHEDULE' | 'PARENT_HEALTH' | 'PARENT_PROFILE' | 'LESSON_PLANS';
