type ChildDetailTab = 'TIMELINE' | 'HEALTH' | 'FORMS';

const LoginScreen: React.FC<{ onLogin: (role: UserRole, userEmail: string) => void }> = ({ onLogin }) => {
  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [email, setEmail] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onLogin(role, email || (role === UserRole.ADMIN ? 'manager@nestflow.app' : role === UserRole.TEACHER ? 'frizzle@sunnyvale.edu' : 'sarah@example.com'));
  };

  return (
    <div className="min-h-screen bg-surface-50 flex items-center justify-center p-6 text-center">
      <div className="bg-white/80 backdrop-blur-md p-10 rounded-[32px] shadow-2xl w-full max-w-md border border-white">
        <div className="mb-10">
          <div className="w-16 h-16 bg-primary-300 rounded-blob mx-auto flex items-center justify-center text-white font-bold text-2xl mb-4">N</div>
          <h1 className="text-4xl font-bold text-gray-800 tracking-tight">NestFlow</h1>
        </div>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="flex bg-gray-100 rounded-2xl p-1 border border-gray-200">
            {(['ADMIN', 'TEACHER', 'PARENT'] as UserRole[]).map((r) => (
              <button 
                key={r}
                type="button" 
                onClick={() => setRole(r)} 
                className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-all ${role === r ? 'bg-white text-primary-600 shadow-sm' : 'text-gray-500'}`}
              >
                {r.charAt(0) + r.slice(1).toLowerCase()}
              </button>
            ))}
          </div>
          <input 
            type="email" 
            placeholder="Work Email" 
            value={email} 
            onChange={(e) => setEmail(e.target.value)} 
            className="w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl outline-none" 
            required 
          />
          <button type="submit" className="w-full py-5 bg-primary-400 text-white font-bold text-lg rounded-2xl shadow-xl shadow-primary-200 hover:scale-[1.02] active:scale-95 transition-all">
            Sign In
          </button>
        </form>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<{ role: UserRole, email: string } | null>(null);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [activeSection, setActiveSection] = useState<AppSection>('DAILY_OPS');
  const [navStack, setNavStack] = useState<AppSection[]>(['DAILY_OPS']);

  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [staff] = useState<StaffMember[]>(INITIAL_STAFF);
  const [shifts, setShifts] = useState<ShiftAssignment[]>(INITIAL_SHIFTS);
  const [activities, setActivities] = useState<Activity[]>(INITIAL_ACTIVITIES);
  const [leads, setLeads] = useState(INITIAL_LEADS);
  const [lessonPlans] = useState<LessonPlan[]>(INITIAL_LESSON_PLANS);
  const [signedForms, setSignedForms] = useState<SignedConsentForm[]>(INITIAL_SIGNED_FORMS);

  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('toddlers');
  const [selectedChildId, setSelectedChildId] = useState<string | null>(null);
  const [selectedLessonPlanId, setSelectedLessonPlanId] = useState<string | null>(null);
  const [activeChildTab, setActiveChildTab] = useState<ChildDetailTab>('TIMELINE');
  const [signingForm, setSigningForm] = useState<ConsentTemplate | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- DERIVED STATE ---
  const myChildren = useMemo(() => {
    if (currentUser?.role !== UserRole.PARENT) return [];
    return children.filter(c => c.id === '1'); // Mock: Sarah always sees Leo
  }, [children, currentUser]);

  const selectedChild = useMemo(() => children.find(c => c.id === selectedChildId), [children, selectedChildId]);
  const selectedLessonPlan = useMemo(() => lessonPlans.find(lp => lp.id === selectedLessonPlanId), [lessonPlans, selectedLessonPlanId]);

  const centerHealth = useMemo(() => {
    const enrolled = children.filter(c => c.enrollmentStatus === 'ENROLLED');
    return {
      occupancy: Math.round((enrolled.length / 44) * 100),
      ar: 4250,
      ratios: [
        { name: 'Infants', val: '4:1', safe: true },
        { name: 'Toddlers', val: '6:1', safe: true },
        { name: 'Preschool', val: '12:1', safe: false }
      ]
    };
  }, [children]);

  // --- ACTIONS ---
  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const navigateTo = (section: AppSection) => {
    setActiveSection(section);
    setNavStack(prev => [...prev, section]);
  };

  const goBack = () => {
    if (navStack.length > 1) {
      const newStack = [...navStack];
      newStack.pop();
      setNavStack(newStack);
      setActiveSection(newStack[newStack.length - 1]);
    }
  };

  const handleCheckInAll = () => {
    setChildren(prev => prev.map(c => 
      c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED' 
        ? { ...c, status: 'PRESENT', lastActivityTime: 'Just now' } 
        : c
    ));
    showToast(`Checked in all children in ${selectedClassroomId}`);
  };

  const handleQuickAdd = () => {
    showToast("Quick Add modal triggered", "success");
  };

  const handleToggleShift = (staffId: string, day: string) => {
    const existing = shifts.find(s => s.staffId === staffId && s.day === day);
    const nextType = SHIFT_TYPES[(SHIFT_TYPES.indexOf(existing?.type || 'OFF') + 1) % SHIFT_TYPES.length];
    setShifts(prev => {
      const filtered = prev.filter(s => !(s.staffId === staffId && s.day === day));
      return nextType === 'OFF' ? filtered : [...filtered, { staffId, day, type: nextType }];
    });
  };

  const handleLeadStatusChange = (leadId: string) => {
    const statuses = ['Inquiry', 'Tour Scheduled', 'Waitlist'];
    setLeads(prev => prev.map(l => {
      if (l.id === leadId) {
        const next = statuses[(statuses.indexOf(l.status) + 1) % statuses.length];
        return { ...l, status: next };
      }
      return l;
    }));
    showToast("Lead status advanced");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && selectedChildId) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const base64 = ev.target?.result as string;
        setChildren(prev => prev.map(c => c.id === selectedChildId ? { ...c, avatarUrl: base64 } : c));
        showToast("Profile picture updated!");
      };
      reader.readAsDataURL(file);
    }
  };

  // --- RENDER HELPERS ---

  const SidebarContent = () => (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3 pl-2">
          {currentUser?.role === UserRole.PARENT ? 'Leo\'s Portal' : 'Main Hub'}
        </h3>
        {currentUser?.role === UserRole.PARENT ? (
          <>
            <button onClick={() => { navigateTo('DAILY_OPS'); setActiveChildTab('TIMELINE'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'DAILY_OPS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600'}`}>🏠 Daily Feed</button>
            <button onClick={() => { navigateTo('PARENT_HEALTH'); setActiveChildTab('HEALTH'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'PARENT_HEALTH' ? 'bg-primary-100 text-primary-600' : 'text-gray-600'}`}>🏥 Health Log</button>
            <button onClick={() => { navigateTo('CONSENT_FORMS'); setActiveChildTab('FORMS'); }} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'CONSENT_FORMS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600'}`}>📜 Consent Forms</button>
          </>
        ) : (
          <>
            {currentUser?.role === UserRole.ADMIN && (
              <>
                <button onClick={() => navigateTo('CRM_DASHBOARD')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'CRM_DASHBOARD' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>📊 CRM Dashboard</button>
                <button onClick={() => navigateTo('STAFF_SCHEDULE')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'STAFF_SCHEDULE' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🗓️ Staff Schedule</button>
              </>
            )}
            <button onClick={() => navigateTo('LESSON_PLANS')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'LESSON_PLANS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🍎 Lesson Plans</button>
            <button onClick={() => navigateTo('DAILY_OPS')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'DAILY_OPS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>🏠 Live Feed</button>
            <button onClick={() => navigateTo('STUDENTS')} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-bold ${activeSection === 'STUDENTS' ? 'bg-primary-100 text-primary-600' : 'text-gray-600 hover:bg-gray-50'}`}>👶 Students</button>
          </>
        )}
      </div>
    </div>
  );

  const ListPanelContent = () => {
    switch (activeSection) {
      case 'CRM_DASHBOARD':
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-left-4">
            <h2 className="text-xl font-bold text-gray-800">Pipeline</h2>
            {['Inquiry', 'Tour Scheduled', 'Waitlist'].map(st => (
              <div key={st} className="p-4 bg-white border border-gray-100 rounded-nest">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">{st}</p>
                <div className="space-y-2">
                  {leads.filter(l => l.status === st).map(l => (
                    <div key={l.id} onClick={() => handleLeadStatusChange(l.id)} className="p-3 bg-surface-50 rounded-xl border border-gray-100 flex justify-between items-center cursor-pointer hover:border-primary-200 transition-colors group">
                      <div>
                        <p className="text-sm font-bold text-gray-700">{l.childName}</p>
                        <p className="text-[10px] text-gray-400">{l.parentName}</p>
                      </div>
                      <span className="text-[10px] text-primary-300 group-hover:text-primary-500 font-bold transition-colors">Move →</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        );
      case 'STAFF_SCHEDULE':
        return (
          <div className="space-y-6 animate-in fade-in">
            <h2 className="text-xl font-bold text-gray-800">Coverage</h2>
            <div className="bg-white rounded-nest border border-gray-100 overflow-x-auto shadow-sm p-4">
              <table className="w-full text-left text-[11px]">
                <thead className="border-b border-gray-50">
                  <tr>
                    <th className="pb-3 text-gray-400 uppercase font-bold tracking-widest">Teacher</th>
                    {DAYS.map(d => <th key={d} className="pb-3 text-center text-gray-400 uppercase font-bold">{d}</th>)}
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {INITIAL_STAFF.map(s => (
                    <tr key={s.id} className="group">
                      <td className="py-4 font-bold text-gray-700">{s.name.split(' ')[0]}</td>
                      {DAYS.map(d => {
                        const sh = shifts.find(x => x.staffId === s.id && x.day === d);
                        return (
                          <td key={d} className="py-2 text-center">
                            <button 
                              onClick={() => handleToggleShift(s.id, d)}
                              className={`w-10 h-6 rounded-full text-[8px] font-black border transition-all ${
                                sh?.type === 'OPEN' ? 'bg-green-50 border-green-200 text-green-600' :
                                sh?.type === 'MID' ? 'bg-blue-50 border-blue-200 text-blue-600' :
                                sh?.type === 'CLOSE' ? 'bg-orange-50 border-orange-200 text-orange-600' :
                                'bg-gray-50 border-gray-100 text-gray-300'
                              }`}
                            >
                              {sh?.type || 'OFF'}
                            </button>
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      case 'LESSON_PLANS':
        return (
          <div className="space-y-4">
            <h2 className="text-xl font-bold text-gray-800">Curriculum</h2>
            {lessonPlans.map(lp => (
              <div key={lp.id} onClick={() => setSelectedLessonPlanId(lp.id)} className={`p-5 rounded-nest border transition-all cursor-pointer ${selectedLessonPlanId === lp.id ? 'bg-white border-primary-300 shadow-md ring-2 ring-primary-50' : 'bg-white border-gray-100'}`}>
                <div className="flex justify-between items-center mb-1">
                  <h4 className="font-bold text-gray-800">{lp.title}</h4>
                  <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${lp.status === 'PUBLISHED' ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'}`}>{lp.status}</span>
                </div>
                <p className="text-xs text-gray-400">Theme: {lp.theme}</p>
              </div>
            ))}
          </div>
        );
      default:
        const listChildren = currentUser?.role === UserRole.PARENT ? myChildren : children.filter(c => c.classroomId === selectedClassroomId);
        return (
          <div className="space-y-4">
            <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Roster</h3>
            {listChildren.map(c => (
              <NestCard key={c.id} child={c} selected={selectedChildId === c.id} onClick={() => setSelectedChildId(c.id)} />
            ))}
          </div>
        );
    }
  };

  const DetailPanelContent = () => {
    if (activeSection === 'CRM_DASHBOARD') {
      return (
        <div className="flex flex-col h-full bg-white p-8 space-y-10 overflow-y-auto animate-in slide-in-from-right-4">
          <div>
            <h3 className="text-2xl font-bold text-gray-800">Operations</h3>
            <p className="text-xs text-primary-400 font-bold uppercase mt-1">Real-time health</p>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-primary-50 p-6 rounded-[32px] border border-primary-100">
              <p className="text-[10px] font-bold text-primary-400 uppercase tracking-widest mb-1">Occupancy</p>
              <p className="text-3xl font-bold text-primary-600">{centerHealth.occupancy}%</p>
              <div className="w-full bg-white h-1 rounded-full mt-3 overflow-hidden">
                <div className="bg-primary-300 h-full" style={{ width: `${centerHealth.occupancy}%` }} />
              </div>
            </div>
            <div className="bg-accent-300/10 p-6 rounded-[32px] border border-accent-300/20">
              <p className="text-[10px] font-bold text-accent-300 uppercase tracking-widest mb-1">Pending AR</p>
              <p className="text-3xl font-bold text-accent-300">${centerHealth.ar}</p>
            </div>
          </div>
          <div className="space-y-4">
            <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Ratio Watch</h4>
            {centerHealth.ratios.map(r => (
              <div key={r.name} className="flex justify-between items-center p-4 bg-surface-50 rounded-2xl border border-gray-100">
                <span className="text-sm font-bold text-gray-700">{r.name}</span>
                <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${r.safe ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>{r.val}</span>
              </div>
            ))}
          </div>
        </div>
      );
    }

    if (selectedLessonPlan && activeSection === 'LESSON_PLANS') {
      return (
        <div className="flex flex-col h-full bg-white p-8 overflow-y-auto animate-in slide-in-from-right-4">
          <h3 className="text-2xl font-bold text-gray-800 mb-6">{selectedLessonPlan.title}</h3>
          <div className="space-y-6">
            <section className="p-5 bg-surface-50 rounded-3xl border border-gray-100">
              <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">Objectives</h4>
              {selectedLessonPlan.objectives.map((o, i) => <div key={i} className="text-xs text-gray-700 font-medium mb-2">✨ {o}</div>)}
            </section>
            <section className="space-y-4">
              <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Weekly Flow</h4>
              {selectedLessonPlan.activities.map(a => (
                <div key={a.day} className="pl-4 border-l-2 border-primary-100">
                  <p className="text-xs font-bold text-primary-400 uppercase">{a.day}: {a.activityName}</p>
                  <p className="text-[10px] text-gray-400 mt-1">{a.description}</p>
                </div>
              ))}
            </section>
          </div>
        </div>
      );
    }

    if (selectedChild) {
      const childActivities = activities.filter(a => a.childId === selectedChild.id);
      return (
        <div className="flex flex-col h-full bg-white overflow-hidden">
          <div className="h-40 bg-primary-100 flex items-end p-6 gap-4 relative">
            <div className="relative group">
              <img src={selectedChild.avatarUrl} className="w-20 h-20 rounded-full border-4 border-white shadow-xl bg-white object-cover" />
              <button onClick={() => fileInputRef.current?.click()} className="absolute -bottom-1 -right-1 w-8 h-8 bg-white rounded-full border border-gray-100 shadow-md flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">📸</button>
            </div>
            <div className="mb-4">
              <h2 className="text-2xl font-bold text-gray-800 leading-tight">{selectedChild.firstName} {selectedChild.lastName}</h2>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">{selectedChild.classroom}</p>
            </div>
          </div>
          <div className="flex border-b border-gray-100 px-6 gap-6">
            {['TIMELINE', 'HEALTH', 'FORMS'].map(tab => (
              <button 
                key={tab} 
                onClick={() => setActiveChildTab(tab as any)}
                className={`py-4 text-[10px] font-bold relative transition-colors ${activeChildTab === tab ? 'text-primary-500' : 'text-gray-400'}`}
              >
                {tab}
                {activeChildTab === tab && <div className="absolute bottom-0 left-0 right-0 h-1 bg-primary-300 rounded-t-full" />}
              </button>
            ))}
          </div>
          <div className="flex-1 overflow-y-auto p-8 bg-surface-50/30">
            {activeChildTab === 'TIMELINE' ? (
              childActivities.length > 0 ? childActivities.map(act => <ActivityFeedItem key={act.id} activity={act} />) : <p className="text-center text-gray-400 text-xs mt-10">No activities recorded today.</p>
            ) : activeChildTab === 'HEALTH' ? (
              <div className="space-y-6">
                <div className="bg-red-50 p-4 rounded-2xl border border-red-100"><p className="text-[10px] font-bold text-red-400 uppercase tracking-widest mb-1">Critical Allergy</p><p className="text-sm font-bold text-red-800">Peanuts - EpiPen in Classroom Bag 1A</p></div>
                <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm"><p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Doctor</p><p className="text-sm font-bold text-gray-700">Dr. Sarah Miller (555-0912)</p></div>
              </div>
            ) : (
              <div className="space-y-3">
                {CONSENT_TEMPLATES.map(t => {
                  const isSigned = signedForms.some(f => f.childId === selectedChild.id && f.templateId === t.id);
                  return (
                    <div key={t.id} className={`p-4 rounded-2xl border flex justify-between items-center ${isSigned ? 'bg-white border-gray-100' : 'bg-primary-50 border-primary-200'}`}>
                      <div><p className="text-xs font-bold text-gray-800">{t.title}</p><p className="text-[9px] text-gray-400 uppercase font-black">{isSigned ? 'Compliant' : 'Missing Signature'}</p></div>
                      {!isSigned && <button onClick={() => setSigningForm(t)} className="text-[9px] font-bold bg-primary-400 text-white px-2 py-1 rounded-full">Sign</button>}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      );
    }

    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 p-8 text-center bg-gray-50/50">
        <div className="w-20 h-20 bg-white rounded-blob flex items-center justify-center mb-6 text-2xl shadow-inner">🌱</div>
        <h3 className="text-lg font-bold text-gray-600">Select an item</h3>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); }} />;

  return (
    <>
      <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setSelectedChildId(null); setActiveSection('DAILY_OPS'); setNavStack(['DAILY_OPS']); }}
        onGoHome={() => { setActiveSection('DAILY_OPS'); setNavStack(['DAILY_OPS']); }}
        onGoBack={goBack}
        canGoBack={navStack.length > 1}
        onCheckIn={handleCheckInAll}
        onQuickAdd={handleQuickAdd}
      />
      {signingForm && (
        <div className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6 animate-in zoom-in duration-200">
          <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl p-10 space-y-8">
            <h3 className="text-3xl font-bold text-gray-800">{signingForm.title}</h3>
            <p className="text-sm text-gray-600 leading-relaxed font-medium bg-surface-50 p-6 rounded-3xl border border-gray-100">{signingForm.content}</p>
            <button 
              onClick={() => {
                setSignedForms(prev => [...prev, { id: `sf-${Date.now()}`, childId: selectedChildId!, templateId: signingForm.id, status: 'SIGNED', signedAt: new Date().toLocaleDateString(), signerName: 'Guardian' }]);
                setSigningForm(null);
                showToast("Document signed successfully!");
              }} 
              className="w-full py-5 bg-primary-400 text-white font-bold text-lg rounded-[24px] shadow-xl"
            >
              Sign & Approve
            </button>
          </div>
        </div>
      )}
      {toast && (
        <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 px-6 py-4 rounded-2xl shadow-2xl font-bold text-white z-[110] animate-in slide-in-from-bottom-8 ${toast.type === 'success' ? 'bg-gray-900/90' : 'bg-red-500'}`}>
          {toast.message}
        </div>
      )}
    </>
  );
};

