const LoginScreen: React.FC<{ onLogin: (role: UserRole, userEmail: string) => void }> = ({ onLogin }) => {
  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [email, setEmail] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onLogin(role, email || (role === UserRole.ADMIN ? 'manager@nestflow.app' : role === UserRole.TEACHER ? 'frizzle@sunnyvale.edu' : 'sarah@example.com'));
  };

  return (
    <div className="min-h-screen bg-surface-50 flex items-center justify-center p-6 text-center">
      <div className="bg-white/80 backdrop-blur-md p-10 rounded-[32px] shadow-2xl w-full max-w-md border border-white">
