          <p className="text-gray-400 text-sm mt-1 font-medium tracking-tight">Center Management Platform</p>
        </div>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="flex bg-gray-100 rounded-2xl p-1 border border-gray-200">
            {(['ADMIN', 'TEACHER', 'PARENT'] as UserRole[]).map((r) => (
              <button 
                key={r}
                type="button" 
                onClick={() => setRole(r)} 
                className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-all ${role === r ? 'bg-white text-primary-600 shadow-sm' : 'text-gray-500'}`}
              >
                {r.charAt(0) + r.slice(1).toLowerCase()}
