  const [signedForms, setSignedForms] = useState<SignedConsentForm[]>(INITIAL_SIGNED_FORMS);

  const [selectedClassroomId, setSelectedClassroomId] = useState<string>('toddlers');
  const [selectedChildId, setSelectedChildId] = useState<string | null>(null);
  const [selectedLessonPlanId, setSelectedLessonPlanId] = useState<string | null>(null);
  const [activeChildTab, setActiveChildTab] = useState<ChildDetailTab>('TIMELINE');
  const [signingForm, setSigningForm] = useState<ConsentTemplate | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- ACTIONS ---
  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const navigateTo = (section: AppSection) => {
    setActiveSection(section);
    setNavStack(prev => [...prev, section]);
    setSelectedChildId(null);
  };

  const goBack = () => {
    if (navStack.length > 1) {
      const newStack = [...navStack];
      newStack.pop();
      setNavStack(newStack);
      setActiveSection(newStack[newStack.length - 1]);
    }
  };

  const handleToggleShift = (staffId: string, day: string) => {
    const existing = shifts.find(s => s.staffId === staffId && s.day === day);
    const nextType = SHIFT_TYPES[(SHIFT_TYPES.indexOf(existing?.type || 'OFF') + 1) % SHIFT_TYPES.length];
    setShifts(prev => {
      const filtered = prev.filter(s => !(s.staffId === staffId && s.day === day));
      return nextType === 'OFF' ? filtered : [...filtered, { staffId, day, type: nextType }];
    });
  };

  const handleLeadStatusChange = (leadId: string) => {
    const statuses = ['Inquiry', 'Tour Scheduled', 'Waitlist'];
    setLeads(prev => prev.map(l => {
      if (l.id === leadId) {
        const next = statuses[(statuses.indexOf(l.status) + 1) % statuses.length];
        return { ...l, status: next };
      }
      return l;
    }));
    showToast("Lead status advanced");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && selectedChildId) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const base64 = ev.target?.result as string;
        setChildren(prev => prev.map(c => c.id === selectedChildId ? { ...c, avatarUrl: base64 } : c));
        showToast("Profile picture updated!");
      };
      reader.readAsDataURL(file);
    }
  };

  // --- DERIVED STATE ---
  const myChildren = useMemo(() => {
    if (currentUser?.role !== UserRole.PARENT) return [];
    return children.filter(c => c.id === '1'); 
  }, [children, currentUser]);

  const selectedChild = useMemo(() => children.find(c => c.id === selectedChildId), [children, selectedChildId]);
  const selectedLessonPlan = useMemo(() => lessonPlans.find(lp => lp.id === selectedLessonPlanId), [lessonPlans, selectedLessonPlanId]);

  const centerHealth = useMemo(() => {
    const enrolled = children.filter(c => c.enrollmentStatus === 'ENROLLED');
    return {
      occupancy: Math.round((enrolled.length / 44) * 100),
      ar: 4250,
      ratios: [
        { name: 'Infants', val: '4:1', safe: true },
        { name: 'Toddlers', val: '6:1', safe: true },
        { name: 'Preschool', val: '12:1', safe: false }
