      default:
        const listChildren = currentUser?.role === UserRole.PARENT ? myChildren : children.filter(c => c.classroomId === selectedClassroomId);
        return (
          <div className="space-y-4">
            <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest pl-1">Live Student Roster</h3>
