                  return (
                    <div key={t.id} className={`p-4 rounded-2xl border flex justify-between items-center transition-all ${isSigned ? 'bg-white border-gray-100 opacity-60' : 'bg-primary-50 border-primary-200 shadow-sm'}`}>
