  const analytics = useMemo(() => {
    const enrolled = children.filter(c => c.enrollmentStatus === 'ENROLLED');
    const presentCount = enrolled.filter(c => c.status === 'PRESENT').length;
    const totalRev = invoices.filter(i => i.status === 'PAID').reduce((s, i) => s + parseFloat(i.amount), 0);
    const pendRev = invoices.filter(i => i.status === 'PENDING').reduce((s, i) => s + parseFloat(i.amount), 0);
    return {
      occupancy: Math.round((enrolled.length / 30) * 100),
      presentCount,
      totalRev,
      pendRev
    };
  }, [children, invoices]);

  // --- SUB-PANEL RENDERING ---

  const DetailPanelContent = () => {
    switch (activeSection) {
      case 'BILLING':
        return (
