            <div className="grid grid-cols-2 gap-4">
              <div className="bg-brand-teal/5 p-6 rounded-[40px] border border-brand-teal/10 shadow-sm">
                <p className="text-[10px] font-black text-brand-teal uppercase mb-1">Total Revenue</p>
                <p className="text-3xl font-black text-brand-blue tracking-tighter">${analytics.totalRev}</p>
              </div>
              <div className="bg-accent-300/10 p-6 rounded-[40px] border border-accent-300/20 shadow-sm">
                <p className="text-[10px] font-black text-accent-300 uppercase mb-1">Awaiting</p>
                <p className="text-3xl font-black text-accent-300 tracking-tighter">${analytics.pendRev}</p>
              </div>
            </div>
            <div className="space-y-4">
