                <div key={inv.id} className="p-6 bg-white border border-slate-100 rounded-[32px] flex justify-between items-center shadow-sm">
                  <div>
                    <p className="text-sm font-black text-brand-blue">{inv.title}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">{inv.date}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-black text-slate-900 mb-1">${inv.amount}</p>
                    {inv.status !== 'PAID' ? (
                      <button onClick={() => handlePayInvoice(inv.id)} className="bg-brand-teal text-white text-[9px] font-black px-3 py-1 rounded-full uppercase">Pay</button>
                    ) : (
                      <span className="text-[9px] font-black px-3 py-1 rounded-full uppercase bg-green-100 text-green-600 font-black">Paid</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'MESSAGES':
        return (
          <div className="flex flex-col h-full animate-in slide-in-from-right-8 bg-white">
            <div className="p-8 border-b border-slate-50 flex justify-between items-center">
