                <p className="text-[10px] font-black text-brand-teal uppercase mt-1">Direct Communication</p>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-4 bg-slate-50/20">
              {messages.map((m, i) => (
                <div key={i} className={`max-w-[80%] p-5 rounded-[32px] ${m.sender === 'You' ? 'bg-brand-teal text-white ml-auto rounded-tr-none' : 'bg-white border border-slate-100 rounded-tl-none'} shadow-sm`}>
                  <p className="text-sm font-bold">{m.text}</p>
                  <p className="text-[8px] font-black mt-2 uppercase opacity-60 text-right">{m.time}</p>
                </div>
              ))}
            </div>
            <div className="p-6 border-t border-slate-100">
              <div className="flex gap-2">
                <input 
