                <button onClick={handleSendMessage} className="w-14 h-14 bg-brand-teal rounded-full flex items-center justify-center text-white shadow-lg">↑</button>
              </div>
            </div>
          </div>
        );
      case 'ANALYTICS':
        return (
          <div className="p-8 space-y-10 animate-in fade-in slide-in-from-right-8 h-full overflow-y-auto">
            <h3 className="text-3xl font-black text-brand-blue tracking-tight">Center Reports</h3>
            <div className="space-y-6">
              <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Occupancy Trend</p>
                <div className="h-40 bg-slate-50 rounded-[32px] flex items-end p-4 gap-2">
                   {[40, 70, 50, 90, 85, 95].map((h, i) => <div key={i} className="flex-1 bg-brand-teal/20 rounded-t-lg" style={{height: `${h}%`}} />)}
                </div>
              </div>
              <button onClick={handleExportData} className="w-full py-4 bg-brand-blue text-white font-black rounded-3xl shadow-xl hover:scale-[1.02] transition-all">Export Detailed CSV</button>
            </div>
          </div>
        );
      case 'LESSON_PLANS':
        if (selectedLessonPlanId) {
          const lp = lessonPlans.find(l => l.id === selectedLessonPlanId);
          return (
