            <h3 className="text-3xl font-black text-brand-blue">App Settings</h3>
            <div className="space-y-4">
              {['Profile Privacy', 'Notification Preferences', 'Billing Auto-Pay', 'API Connections'].map(s => (
                <div key={s} className="p-6 bg-white border border-slate-100 rounded-[32px] flex justify-between items-center shadow-sm">
                  <span className="text-sm font-black text-brand-blue">{s}</span>
                  <div className="w-12 h-6 bg-brand-teal rounded-full relative"><div className="absolute right-1 top-1 w-4 h-4 bg-white rounded-full"></div></div>
                </div>
              ))}
            </div>
          </div>
        );
      default:
        if (selectedChildId) {
          const child = children.find(c => c.id === selectedChildId);
          const childActivities = activities.filter(a => a.childId === child?.id);
          return (
            <div className="flex flex-col h-full animate-in slide-in-from-right-8 bg-white overflow-hidden">
