                     {child?.enrollmentStatus === 'ENROLLED' && (
                       <select 
                        value={child?.status} 
                        onChange={(e) => handleAttendanceChange(child!.id, e.target.value as any)}
                        className="text-[9px] font-black bg-brand-yellow/30 border-none rounded-full px-2 outline-none cursor-pointer"
                       >
                         <option value="PRESENT">In</option>
                         <option value="ABSENT">Away</option>
                         <option value="CHECKED_OUT">Out</option>
                       </select>
