              <div key={c.id} className="p-6 bg-white border border-slate-100 rounded-[40px] shadow-sm flex items-center justify-between group hover:border-brand-teal transition-all">
                <div className="flex items-center gap-4">
                   <img src={c.avatarUrl} className="w-12 h-12 rounded-2xl bg-slate-100 border-2 border-white" />
                   <div><p className="text-sm font-black text-brand-blue">{c.firstName}</p><p className="text-[10px] text-slate-400 font-bold uppercase">Applied Nov 20</p></div>
