                <button onClick={() => handleEnrollChild(c.id)} className="px-4 py-2 bg-brand-teal/10 text-brand-teal rounded-2xl text-[10px] font-black uppercase hover:bg-brand-teal hover:text-white transition-all">Enroll</button>
              </div>
            ))}
            {children.filter(c => c.enrollmentStatus === 'WAITLIST').length === 0 && <p className="text-center text-slate-400 text-xs font-black uppercase tracking-widest">Queue cleared</p>}
          </div>
        );
      case 'BILLING':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Family Accounts</h2>
            {children.filter(c => c.enrollmentStatus === 'ENROLLED').map(c => (
              <div key={c.id} className="p-6 bg-white border border-slate-100 rounded-[40px] shadow-sm flex items-center justify-between group cursor-pointer hover:border-brand-teal transition-all">
                <p className="text-sm font-black text-brand-blue">{c.firstName}'s Family</p>
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-green-500"></span>
                  <span className="text-[10px] font-black text-slate-400 uppercase">Auto-Pay Active</span>
                </div>
              </div>
            ))}
          </div>
        );
      case 'TEAM':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Compass Staffing</h2>
            {staff.map(s => (
              <div key={s.id} className="p-6 bg-white border border-slate-100 rounded-[40px] shadow-sm flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <img src={s.avatarUrl} className="w-12 h-12 rounded-full border-2 border-white shadow-sm" />
                  <div><p className="text-sm font-black text-brand-blue">{s.name}</p><p className="text-[10px] text-brand-teal font-black uppercase tracking-widest">{s.role}</p></div>
