                <span className="text-sm font-black text-brand-blue">{int}</span>
                <span className="text-[9px] font-black text-brand-teal uppercase tracking-widest">Active Sync</span>
              </div>
            ))}
          </div>
        );
      case 'SETTINGS':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Configuration</h2>
            <div className="space-y-4">
               {['General', 'Security', 'Billing Info', 'Permissions'].map(s => (
                 <div key={s} className="p-5 bg-white border border-slate-100 rounded-[32px] font-black text-brand-blue text-sm shadow-sm cursor-pointer hover:bg-slate-50 transition-all">{s}</div>
               ))}
            </div>
          </div>
        );
      default:
        const roomChildren = children.filter(c => c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED');
        return (
          <div className="space-y-5">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Room Roster</h3>
            {roomChildren.map(c => (
              <NestCard key={c.id} child={c} selected={selectedChildId === c.id} onClick={() => { setActiveSection('DAILY_OPS'); setSelectedChildId(c.id); }} />
            ))}
          </div>
        );
    }
  };

  const SidebarContent = () => (
    <div className="space-y-12">
      <div className="space-y-1.5">
        <h3 className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] mb-6 pl-4">Compass Hub</h3>
        {[
          { id: 'DAILY_OPS', label: 'Roster', icon: '🧭' },
          { id: 'MESSAGES', label: 'Messages', icon: '💬' },
          { id: 'BILLING', label: 'Billing', icon: '💰' },
          { id: 'LESSON_PLANS', label: 'Curriculum', icon: '📖' },
        ].map(item => (
          <button key={item.id} onClick={() => { setActiveSection(item.id as AppSection); setSelectedChildId(null); setSelectedLessonPlanId(null); }} className={`w-full text-left px-5 py-4 rounded-2xl text-sm font-black transition-all ${activeSection === item.id ? 'bg-brand-teal text-white shadow-xl shadow-brand-teal/20' : 'text-slate-500 hover:bg-slate-50'}`}>
            <span className="mr-4 opacity-70">{item.icon}</span> {item.label}
          </button>
        ))}
      </div>
      <div className="space-y-1.5">
        <h3 className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] mb-6 pl-4">Admin Center</h3>
        {[
          { id: 'ENROLLMENT', label: 'Enrollment', icon: '📝' },
          { id: 'ANALYTICS', label: 'Analytics', icon: '📊' },
          { id: 'TEAM', label: 'Staffing', icon: '👥' },
          { id: 'INTEGRATIONS', label: 'Integrations', icon: '🔗' },
          { id: 'SETTINGS', label: 'Settings', icon: '⚙️' },
        ].map(item => (
          <button key={item.id} onClick={() => { setActiveSection(item.id as AppSection); setSelectedChildId(null); setSelectedLessonPlanId(null); }} className={`w-full text-left px-5 py-4 rounded-2xl text-sm font-black transition-all ${activeSection === item.id ? 'bg-brand-teal text-white shadow-xl shadow-brand-teal/20' : 'text-slate-500 hover:bg-slate-50'}`}>
            <span className="mr-4 opacity-70">{item.icon}</span> {item.label}
          </button>
        ))}
      </div>
    </div>
  );

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); }} />;

  return (
    <>
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setActiveSection('DAILY_OPS'); }}
        onGoHome={() => { setActiveSection('DAILY_OPS'); setSelectedChildId(null); }}
        onCheckIn={handleCheckInAll}
        onQuickAdd={() => showToast("Quick Log Triggered!")}
      />
      {toast && (
        <div className={`fixed bottom-12 left-1/2 -translate-x-1/2 px-12 py-5 rounded-[32px] shadow-3xl font-black text-white z-[200] animate-in slide-in-from-bottom-12 ${toast.type === 'success' ? 'bg-brand-blue/95 backdrop-blur-md' : 'bg-red-500'}`}>
          {toast.message}
        </div>
      )}
    </>
  );
};

export default App;

