              </div>
            ))}
          </div>
        );
      default:
        return (
          <div className="space-y-5">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Live Activity Hub</h3>
            {accessibleChildren.map(c => (
              <NestCard key={c.id} child={c} selected={selectedChildId === c.id} onClick={() => setSelectedChildId(c.id)} />
            ))}
          </div>
        );
    }
  };

  const SidebarContent = () => {
    const role = currentUser?.role;

    const navItems = [
      { id: 'DAILY_OPS', label: 'Home Hub', icon: '🧭', roles: [UserRole.ADMIN, UserRole.TEACHER, UserRole.PARENT] },
      { id: 'MESSAGES', label: 'Messages', icon: '💬', roles: [UserRole.ADMIN, UserRole.TEACHER, UserRole.PARENT] },
      { id: 'BILLING', label: 'Billing', icon: '💰', roles: [UserRole.ADMIN, UserRole.PARENT] },
      { id: 'MY_STUDENTS', label: 'My Kids', icon: '🧸', roles: [UserRole.PARENT] },
      { id: 'STUDENTS', label: 'Students', icon: '🎒', roles: [UserRole.TEACHER] },
      { id: 'SCHEDULE', label: 'My Shift', icon: '⏰', roles: [UserRole.TEACHER] },
      { id: 'LESSON_PLANS', label: 'Curriculum', icon: '📖', roles: [UserRole.ADMIN, UserRole.TEACHER] },
      { id: 'ENROLLMENT', label: 'Enrollment', icon: '📝', roles: [UserRole.ADMIN] },
      { id: 'ANALYTICS', label: 'Analytics', icon: '📊', roles: [UserRole.ADMIN] },
      { id: 'TEAM', label: 'Staffing', icon: '👥', roles: [UserRole.ADMIN] },
      { id: 'INTEGRATIONS', label: 'Integrations', icon: '🔗', roles: [UserRole.ADMIN] },
      { id: 'SETTINGS', label: 'Settings', icon: '⚙️', roles: [UserRole.ADMIN] },
    ].filter(item => item.roles.includes(role!));

    return (
      <div className="space-y-12">
        <div className="space-y-1.5">
          <h3 className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] mb-6 pl-4">{role} PORTAL</h3>
          {navItems.map(item => (
            <button 
              key={item.id} 
              onClick={() => { setActiveSection(item.id as AppSection); setSelectedChildId(null); setSelectedLessonPlanId(null); }} 
              className={`w-full text-left px-5 py-4 rounded-2xl text-sm font-black transition-all ${activeSection === item.id ? 'bg-brand-teal text-white shadow-xl shadow-brand-teal/20' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <span className="mr-4 opacity-70">{item.icon}</span> {item.label}
            </button>
          ))}
        </div>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); setActiveSection('DAILY_OPS'); }} />;

  return (
    <>
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setActiveSection('DAILY_OPS'); }}
        onGoHome={() => { setActiveSection('DAILY_OPS'); setSelectedChildId(null); }}
        onCheckIn={currentUser?.role !== UserRole.PARENT ? handleCheckInAll : undefined}
        onQuickAdd={currentUser?.role !== UserRole.PARENT ? () => showToast("Quick Log Triggered!") : undefined}
      />
      {toast && (
        <div className={`fixed bottom-12 left-1/2 -translate-x-1/2 px-12 py-5 rounded-[32px] shadow-3xl font-black text-white z-[200] animate-in slide-in-from-bottom-12 ${toast.type === 'success' ? 'bg-brand-blue/95 backdrop-blur-md' : 'bg-red-500'}`}>
          {toast.message}
        </div>
      )}
    </>
  );
};

export default App;

