                <div className="bg-accent-300/10 p-6 rounded-[40px] border border-accent-300/20 shadow-sm">
                  <p className="text-[10px] font-black text-accent-300 uppercase mb-1">Awaiting</p>
                  <p className="text-3xl font-black text-accent-300 tracking-tighter">${analytics.pendRev}</p>
                </div>
              </div>
