              <div className="bg-slate-50 p-6 rounded-[32px]">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Required Materials</p>
                 <div className="flex flex-wrap gap-2">
                   {lp?.materials.map((m, i) => (
                     <span key={i} className="px-3 py-1 bg-white border border-slate-200 rounded-full text-[10px] font-black text-slate-500">{m}</span>
