          const child = children.find(c => c.id === selectedChildId);
          const childActivities = activities.filter(a => a.childId === child?.id);
          const isParent = currentUser?.role === UserRole.PARENT;

          return (
            <div className="flex flex-col h-full animate-in slide-in-from-right-8 bg-white overflow-hidden">
              <div className="h-44 bg-brand-teal/10 p-10 flex items-end gap-6 relative">
                 <img src={child?.avatarUrl} className="w-24 h-24 rounded-[32px] border-4 border-white shadow-2xl bg-white" />
                 <div className="mb-2">
                   <h2 className="text-3xl font-black text-brand-blue leading-none">{child?.firstName} {child?.lastName}</h2>
                   <div className="flex gap-2 mt-2">
                     <span className="text-[10px] font-black text-brand-teal bg-white px-2 py-0.5 rounded-full uppercase">{child?.classroom}</span>
                     {!isParent && child?.enrollmentStatus === 'ENROLLED' && (
                       <select 
                        value={child?.status} 
                        onChange={(e) => handleAttendanceChange(child!.id, e.target.value as any)}
