    }
  };

  const ListPanelContent = () => {
    switch (activeSection) {
      case 'ENROLLMENT':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Enrollment Queue</h2>
