    const totalPaid = paidInvoices.reduce((s, i) => s + parseFloat(i.amount), 0);
    const totalPending = pendingInvoices.reduce((s, i) => s + parseFloat(i.amount), 0);
    const collectionRate = enrolled.length > 0 ? Math.round((totalPaid / (totalPaid + totalPending)) * 100) : 0;

    const classroomStats = [
      { name: 'Toddlers 1A', enrolled: enrolled.filter(c => c.classroomId === 'toddlers').length, capacity: 15 },
      { name: 'Infants', enrolled: enrolled.filter(c => c.classroomId === 'infants').length, capacity: 10 },
      { name: 'Pre-K', enrolled: enrolled.filter(c => c.classroomId === 'prek').length, capacity: 20 },
