const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<{ role: UserRole, email: string } | null>(null);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [activeSection, setActiveSection] = useState<AppSection>('DAILY_OPS');

  // App States
  const [children, setChildren] = useState<Child[]>(INITIAL_CHILDREN);
  const [staff] = useState<StaffMember[]>(INITIAL_STAFF);
  const [invoices, setInvoices] = useState<Invoice[]>(INITIAL_INVOICES);
  const [lessonPlans, setLessonPlans] = useState<LessonPlan[]>(INITIAL_LESSON_PLANS);
  const [activities, setActivities] = useState<Activity[]>([]);

  // UI States
  const [selectedChildId, setSelectedChildId] = useState<string | null>(null);
  const [selectedClassroomId] = useState<string>('toddlers');
  const [activeChildTab, setActiveChildTab] = useState<ChildDetailTab>('TIMELINE');
  const [msgInput, setMsgInput] = useState('');
  const [selectedLessonPlanId, setSelectedLessonPlanId] = useState<string | null>(null);
  const [isCreatingLesson, setIsCreatingLesson] = useState(false);

  // --- MESSAGES / CHAT STATE ---
  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const [isTyping, setIsTyping] = useState(false);
  const [messages, setMessages] = useState<Record<string, {sender: string, text: string, time: string}[]>>({
    'leo': [
      { sender: 'Ms. Frizzle', text: 'Hi! Leo had a great morning playing with blocks today.', time: '10:15 AM' },
      { sender: 'You', text: 'That is wonderful to hear! Did he eat all his lunch?', time: '12:30 PM' },
      { sender: 'Ms. Frizzle', text: 'Yes, he finished his apples and turkey wrap!', time: '1:00 PM' }
    ],
    'front-desk': [
      { sender: 'System', text: 'Welcome to Child Care Compass Support.', time: '9:00 AM' }
    ]
  });

  const chatScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (chatScrollRef.current) {
      chatScrollRef.current.scrollTop = chatScrollRef.current.scrollHeight;
    }
  }, [messages, selectedConversationId, isTyping]);

  // Lesson Plan Form State
  const [newLesson, setNewLesson] = useState({
    title: '',
    theme: '',
    objectives: '',
    materials: '',
  });

  // --- ACTIONS ---

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleEnrollChild = (childId: string) => {
    setChildren(prev => prev.map(c => c.id === childId ? { ...c, enrollmentStatus: 'ENROLLED' as const } : c));
    showToast("Child successfully enrolled!");
  };

  const handleAttendanceChange = (childId: string, newStatus: 'PRESENT' | 'ABSENT' | 'CHECKED_OUT') => {
    setChildren(prev => prev.map(c => c.id === childId ? { ...c, status: newStatus, lastActivityTime: 'Just now' } : c));
    const child = children.find(c => c.id === childId);
    if (child) {
      const type = newStatus === 'PRESENT' ? ActivityType.CHECK_IN : ActivityType.CHECK_OUT;
      setActivities(prev => [{
        id: `act-${Date.now()}`,
        childId,
        type,
        title: newStatus === 'PRESENT' ? 'Checked In' : 'Checked Out',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        authorName: currentUser?.email || 'Staff',
      }, ...prev]);
    }
  };

  const handleCheckInAll = () => {
    const targets = children.filter(c => c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED');
    setChildren(prev => prev.map(c => 
      (c.classroomId === selectedClassroomId && c.enrollmentStatus === 'ENROLLED') 
        ? { ...c, status: 'PRESENT' as const, lastActivityTime: 'Just now' } 
        : c
    ));
    showToast(`Checked in ${targets.length} children`);
  };

  const handleSendMessage = () => {
    if (!msgInput.trim() || !selectedConversationId) return;

    const convId = selectedConversationId;
    const userMsg = { 
      sender: 'You', 
      text: msgInput, 
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) 
    };

    setMessages(prev => ({
      ...prev,
      [convId]: [...(prev[convId] || []), userMsg]
    }));

    setMsgInput('');
    setIsTyping(true);

    // Simulate Reply
    setTimeout(() => {
      const replies = [
        "Absolutely, I will check on that right away!",
        "Thanks for letting us know.",
        "That sounds like a plan. See you soon!",
        "Leo is actually napping right now, but I will tell him when he wakes up!",
        "Can do! I'll update the daily report."
      ];
      const randomReply = replies[Math.floor(Math.random() * replies.length)];

      const replyMsg = { 
        sender: convId === 'front-desk' ? 'Compass Support' : 'Ms. Frizzle', 
        text: randomReply, 
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) 
      };

      setMessages(prev => ({
        ...prev,
        [convId]: [...(prev[convId] || []), replyMsg]
      }));
      setIsTyping(false);
    }, 2000);
  };

  const handlePayInvoice = (invId: string) => {
    setInvoices(prev => prev.map(inv => inv.id === invId ? { ...inv, status: 'PAID' } : inv));
    showToast("Payment Successful via Stripe Integration");
  };

  const handleExportData = () => {
    showToast("Data export generated: compass_report.csv");
  };

  const handleSaveLessonPlan = () => {
    if (!newLesson.title || !newLesson.theme) {
      showToast("Please fill in the title and theme", "error");
      return;
    }

    const plan: LessonPlan = {
      id: `lp-${Date.now()}`,
      title: newLesson.title,
      theme: newLesson.theme,
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0],
      objectives: newLesson.objectives.split('\n').filter(o => o.trim()),
      materials: newLesson.materials.split('\n').filter(m => m.trim()),
      status: 'PUBLISHED',
      authorId: 's1',
      classroomId: 'toddlers',
      activities: [
        { day: 'Mon', activityName: 'Introduction', description: 'Begin the theme activities.' }
      ]
    };

    setLessonPlans(prev => [plan, ...prev]);
    setNewLesson({ title: '', theme: '', objectives: '', materials: '' });
    setIsCreatingLesson(false);
    setSelectedLessonPlanId(plan.id);
    showToast("Lesson Plan Published!");
  };

  // --- DERIVED DATA ---

  // Mock: Parents only see "Leo"
  const accessibleChildren = useMemo(() => {
    if (currentUser?.role === UserRole.PARENT) {
      return children.filter(c => c.id === '1');
    }
    return children;
  }, [children, currentUser]);

  const analytics = useMemo(() => {
    const totalCapacity = 40;
    const enrolled = children.filter(c => c.enrollmentStatus === 'ENROLLED');
    const presentCount = enrolled.filter(c => c.status === 'PRESENT').length;
    const absentCount = enrolled.filter(c => c.status === 'ABSENT').length;

    const paidInvoices = invoices.filter(i => i.status === 'PAID');
    const pendingInvoices = invoices.filter(i => i.status === 'PENDING' || i.status === 'OVERDUE');

    const totalPaid = paidInvoices.reduce((s, i) => s + parseFloat(i.amount), 0);
    const totalPending = pendingInvoices.reduce((s, i) => s + parseFloat(i.amount), 0);
