        {navItems.map(item => (
          <button 
            key={item.id} 
            onClick={() => { 
              setActiveSection(item.id as AppSection); 
              setSelectedChildId(null); 
              setSelectedLessonPlanId(null); 
              setIsCreatingLesson(false); 
              setSelectedConversationId(null);
            }} 
            className={`w-full text-left px-5 py-4 rounded-2xl text-sm font-black transition-all ${activeSection === item.id ? 'bg-brand-teal text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <span className="mr-4">{item.icon}</span> {item.label}
          </button>
        ))}
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); setActiveSection('DAILY_OPS'); }} />;

  return (
    <>
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setActiveSection('DAILY_OPS'); }}
        onGoHome={handleGoHome}
        onGoBack={handleGoBack}
        canGoBack={canGoBack}
        onCheckIn={currentUser?.role !== UserRole.PARENT ? handleCheckInAll : undefined}
        onQuickAdd={currentUser?.role !== UserRole.PARENT ? () => showToast("Activity Logged") : undefined}
      />
      {toast && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 px-12 py-5 rounded-[32px] bg-brand-blue text-white z-[200] animate-in slide-in-from-bottom-12">
          {toast.message}
        </div>
      )}
    </>
  );
};

export default App;

