                    ) : (
                      <span className="text-[9px] font-black px-3 py-1 rounded-full uppercase bg-green-100 text-green-600">Paid</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'MESSAGES':
        if (!selectedConversationId) {
          return (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 p-8 text-center animate-in fade-in">
              <div className="text-6xl mb-6">💬</div>
              <h3 className="text-xl font-black text-slate-400">Compass Messaging</h3>
              <p className="text-sm font-bold uppercase tracking-widest mt-2 max-w-[200px]">Select a family or staff member to start chatting</p>
            </div>
          );
        }
        const currentChat = messages[selectedConversationId] || [];
        const contactName = selectedConversationId === 'leo' ? 'Dasher Family' : 
                          selectedConversationId === 'maya' ? 'Sky Family' : 'Support Desk';

        return (
          <div className="flex flex-col h-full animate-in slide-in-from-right-8 bg-white overflow-hidden">
            <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-white/50 backdrop-blur-md sticky top-0 z-10">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-2xl bg-brand-teal/10 flex items-center justify-center text-xl">
                  {selectedConversationId === 'front-desk' ? '🏢' : '👨‍👩‍👧'}
                </div>
                <div>
                  <h3 className="text-xl font-black text-brand-blue leading-none">{contactName}</h3>
