                      : 'bg-white border border-slate-100 text-brand-blue rounded-tl-none'
                    }`}
                  >
                    <p className="text-sm font-bold leading-relaxed">{m.text}</p>
                  </div>
                  <div className="flex items-center gap-2 mt-2 px-2">
                    {m.sender !== 'You' && <span className="text-[8px] font-black text-brand-teal uppercase">{m.sender}</span>}
                    <span className="text-[8px] font-black text-slate-300 uppercase">{m.time}</span>
                  </div>
                </div>
              ))}

              {isTyping && (
                <div className="flex flex-col items-start animate-in fade-in slide-in-from-bottom-2">
