                    : 'bg-white text-brand-blue hover:border-brand-teal border-slate-100'
                }`}
              >
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl ${
                  selectedConversationId === conv.id ? 'bg-white/20' : 'bg-slate-50'
                }`}>
                  {conv.icon}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-center mb-1">
                    <h4 className="text-sm font-black truncate">{conv.name}</h4>
                    <span className={`text-[8px] font-black uppercase ${selectedConversationId === conv.id ? 'text-white/60' : 'text-slate-400'}`}>
                      {conv.time}
                    </span>
                  </div>
                  <p className={`text-[10px] font-bold truncate ${selectedConversationId === conv.id ? 'text-white/80' : 'text-slate-400'}`}>
                    {conv.lastMsg}
                  </p>
                </div>
              </div>
            ))}
          </div>
        );
      case 'TEAM':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Center Staffing</h2>
            {staff.map(s => (
              <div 
                key={s.id} 
                onClick={() => setSelectedStaffId(s.id)}
                className={`p-6 rounded-[40px] border cursor-pointer transition-all flex items-center justify-between shadow-sm ${
                  selectedStaffId === s.id 
                  ? 'bg-brand-blue text-white border-brand-blue shadow-lg' 
                  : 'bg-white text-brand-blue border-slate-100 hover:border-brand-teal'
                }`}
              >
                <div className="flex items-center gap-4">
                  <img src={s.avatarUrl} className="w-12 h-12 rounded-full border-2 border-white shadow-sm" />
                  <div>
                    <p className="text-sm font-black truncate">{s.name}</p>
                    <p className={`text-[10px] font-black uppercase tracking-widest ${selectedStaffId === s.id ? 'text-white/70' : 'text-brand-teal'}`}>
                      {s.role}
                    </p>
                  </div>
                </div>
                <span className={`text-[9px] font-black uppercase ${selectedStaffId === s.id ? 'text-green-300' : 'text-green-500'}`}>On Shift</span>
              </div>
            ))}
          </div>
        );
      case 'SCHEDULE':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">My Work Schedule</h2>
            {['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'].map(day => (
               <div key={day} className="p-6 bg-white border border-slate-100 rounded-[40px] flex justify-between items-center shadow-sm">
                 <span className="font-black text-slate-800">{day}</span>
                 <span className="text-[10px] font-black text-brand-teal bg-brand-teal/5 px-3 py-1 rounded-full">08:00 AM - 04:30 PM</span>
               </div>
            ))}
          </div>
        );
      case 'LESSON_PLANS':
        const lpTitle = currentUser?.role === UserRole.ADMIN ? 'Teacher Curriculums' : 'My Lesson Plans';
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">{lpTitle}</h2>
            {lessonPlans.map(lp => (
              <div 
                key={lp.id} 
                onClick={() => { setSelectedLessonPlanId(lp.id); setIsCreatingLesson(false); }}
                className={`p-6 rounded-[40px] border cursor-pointer transition-all ${selectedLessonPlanId === lp.id ? 'bg-brand-teal text-white shadow-xl shadow-brand-teal/20' : 'bg-white text-brand-blue hover:border-brand-teal'}`}
