            {currentUser?.role === UserRole.TEACHER && (
              <button 
                onClick={() => { setIsCreatingLesson(true); setSelectedLessonPlanId(null); }}
                className="w-full py-4 bg-brand-yellow text-brand-blue font-black rounded-3xl mt-4 shadow-lg shadow-brand-yellow/10"
