                   <h2 className="text-3xl font-black text-brand-blue leading-none">{child?.firstName} {child?.lastName}</h2>
                   <div className="flex gap-2 mt-2">
                     <span className="text-[10px] font-black text-brand-teal bg-white px-2 py-0.5 rounded-full uppercase">{child?.classroom}</span>
                     {!isParent && child?.enrollmentStatus === 'ENROLLED' && (
                       <select 
                        value={child?.status} 
                        onChange={(e) => handleAttendanceChange(child!.id, e.target.value as any)}
                        className="text-[9px] font-black bg-brand-yellow/30 border-none rounded-full px-2 outline-none cursor-pointer"
                       >
                         <option value="PRESENT">In</option>
                         <option value="ABSENT">Away</option>
                         <option value="CHECKED_OUT">Out</option>
                       </select>
                     )}
                   </div>
                 </div>
                 {/* Critical Alert Overlay for Staff */}
                 {isTeacherOrAdmin && child?.allergies && child.allergies.length > 0 && (
                   <div className="absolute top-4 right-4 bg-accent-400 text-white px-3 py-1 rounded-full text-[10px] font-black uppercase shadow-lg animate-pulse">
                     ⚠️ Alert: Health
                   </div>
                 )}
              </div>

              <div className="flex border-b border-slate-50 px-10 gap-8">
                {['TIMELINE', 'HEALTH', 'FORMS'].map(tab => (
                  <button key={tab} onClick={() => setActiveChildTab(tab as any)} className={`py-6 text-[10px] font-black tracking-widest relative ${activeChildTab === tab ? 'text-brand-teal' : 'text-slate-300'}`}>
                    {tab}
                    {activeChildTab === tab && <div className="absolute bottom-0 left-0 right-0 h-1.5 bg-brand-teal rounded-t-full" />}
                  </button>
                ))}
              </div>

              <div className="flex-1 overflow-y-auto p-8 bg-slate-50/10">
                 {activeChildTab === 'TIMELINE' ? (
                   childActivities.length > 0 ? childActivities.map(act => <ActivityFeedItem key={act.id} activity={act} />) : <p className="text-center text-slate-300 text-xs font-black uppercase mt-12">No activity logged yet</p>
                 ) : activeChildTab === 'HEALTH' ? (
                   <div className="space-y-6">
                      <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Allergies & Sensitivities</p>
                        {child?.allergies && child.allergies.length > 0 ? (
                          <div className="flex flex-wrap gap-2">
                            {child.allergies.map((a, i) => (
                              <span key={i} className="bg-red-50 text-red-600 px-3 py-1.5 rounded-full text-[11px] font-black border border-red-100">
                                {a}
                              </span>
                            ))}
                          </div>
                        ) : (
                          <p className="text-xs font-bold text-slate-400">No known allergies</p>
                        )}
                      </div>

                      <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Health Profile</p>
                        <div className="space-y-4">
                           <div className="flex justify-between items-center border-b border-slate-50 pb-3">
                              <span className="text-[11px] font-black text-slate-400 uppercase">Blood Type</span>
                              <span className="text-sm font-black text-brand-blue">O+</span>
                           </div>
                           <div className="flex justify-between items-center border-b border-slate-50 pb-3">
                              <span className="text-[11px] font-black text-slate-400 uppercase">Medication</span>
                              <span className="text-sm font-black text-brand-blue">Daily EpiPen Access Required</span>
                           </div>
                           <div className="flex justify-between items-center">
                              <span className="text-[11px] font-black text-slate-400 uppercase">Pediatrician</span>
                              <span className="text-sm font-black text-brand-blue">Dr. S. Miller (555-0921)</span>
                           </div>
                        </div>
                      </div>

                      {child?.notes && (
                         <div className="bg-brand-yellow/10 p-6 rounded-[32px] border border-brand-yellow/20">
                           <p className="text-[10px] font-black text-brand-blue uppercase mb-2 tracking-widest">Special Staff Notes</p>
                           <p className="text-sm font-medium text-brand-blue leading-relaxed italic">"{child.notes}"</p>
                         </div>
                      )}
                   </div>
                 ) : activeChildTab === 'FORMS' ? (
                   <div className="space-y-4">
                     {isParent && activeSection === 'MY_STUDENTS' && (
                       <>
                         <button className="w-full py-4 bg-brand-teal text-white font-black rounded-2xl shadow-sm">Upload Medical Record</button>
                         <button className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl">Update Emergency Contacts</button>
                       </>
                     )}
                     <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm space-y-4">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Student Documents</p>
                        {[
                          { name: 'Immunization Record 2024', date: 'Signed: Oct 12', status: 'COMPLIANT' },
                          { name: 'Parental Consent Form', date: 'Signed: Aug 15', status: 'SIGNED' },
                          { name: 'Emergency Contact Card', date: 'Updated: Nov 01', status: 'ACTIVE' }
                        ].map((doc, i) => (
                          <div key={i} className="flex justify-between items-center group cursor-pointer">
                            <div>
                               <p className="text-sm font-black text-brand-blue group-hover:text-brand-teal transition-colors">{doc.name}</p>
                               <p className="text-[10px] text-slate-400 font-bold uppercase">{doc.date}</p>
                            </div>
                            <span className="text-[9px] font-black text-brand-teal bg-brand-teal/5 px-2 py-1 rounded-md">{doc.status}</span>
                          </div>
                        ))}
                     </div>
                   </div>
                 ) : (
                   <p className="text-center text-slate-300 text-xs font-black uppercase mt-12 tracking-widest">Confidential Records</p>
                 )}
              </div>
            </div>
          );
        }
        return (
          <div className="h-full flex flex-col items-center justify-center text-slate-300 p-12 text-center">
            <Logo size={120} />
            <h3 className="text-2xl font-black text-slate-400 font-display mt-8">Child Care Compass</h3>
            <p className="text-sm text-slate-300 mt-4 max-w-[240px] font-bold uppercase tracking-widest text-[10px]">{currentUser?.role} PORTAL ACTIVE</p>
          </div>
        );
    }
  };

  const ListPanelContent = () => {
    switch (activeSection) {
      case 'ENROLLMENT':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Enrollment Queue</h2>
            {children.filter(c => c.enrollmentStatus === 'WAITLIST').map(c => (
              <div key={c.id} className="p-6 bg-white border border-slate-100 rounded-[40px] shadow-sm flex items-center justify-between">
                <div className="flex items-center gap-4">
                   <img src={c.avatarUrl} className="w-12 h-12 rounded-2xl" />
                   <div><p className="text-sm font-black text-brand-blue">{c.firstName}</p><p className="text-[10px] text-slate-400 font-bold uppercase">Applied Nov 20</p></div>
                </div>
                <button onClick={() => handleEnrollChild(c.id)} className="px-4 py-2 bg-brand-teal/10 text-brand-teal rounded-2xl text-[10px] font-black uppercase">Approve</button>
              </div>
            ))}
          </div>
        );
      case 'ANALYTICS':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Operational Insights</h2>

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Enrolled</p>
                 <p className="text-2xl font-black text-brand-blue">{children.filter(c => c.enrollmentStatus === 'ENROLLED').length}</p>
              </div>
              <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Center Occupancy</p>
                 <p className="text-2xl font-black text-brand-teal">{analytics.occupancy}%</p>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm">
               <div className="flex justify-between items-center mb-4">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Financial Collection Rate</p>
                  <span className="text-xs font-black text-brand-blue">{analytics.collectionRate}%</span>
               </div>
               <div className="w-full h-2 bg-slate-50 rounded-full">
                  <div className="h-full bg-brand-yellow rounded-full transition-all duration-700" style={{ width: `${analytics.collectionRate}%` }} />
               </div>
            </div>

            <div className="bg-brand-blue p-6 rounded-[32px] text-white shadow-xl shadow-brand-blue/10">
               <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-1">Pending Waitlist</p>
               <div className="flex justify-between items-center">
                 <p className="text-2xl font-black">{analytics.waitlistCount} Leads</p>
                 <button onClick={() => setActiveSection('ENROLLMENT')} className="text-[10px] font-black bg-white/20 px-3 py-1.5 rounded-full hover:bg-white/30 transition-all uppercase">View Queue</button>
               </div>
            </div>
          </div>
        );
      case 'MESSAGES':
        const conversations = [
          { id: 'leo', name: 'Dasher Family', lastMsg: 'Leo had a great morning...', time: '1:00 PM', icon: '👨‍👩‍👧' },
          { id: 'maya', name: 'Sky Family', lastMsg: 'Thank you for the update!', time: 'Yesterday', icon: '👨‍👩‍👦' },
          { id: 'front-desk', name: 'Compass Support', lastMsg: 'How can we help you?', time: 'Mon', icon: '🏢' },
        ];
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Conversations</h2>
            {conversations.map(conv => (
              <div 
                key={conv.id} 
                onClick={() => setSelectedConversationId(conv.id)}
                className={`p-6 rounded-[40px] border cursor-pointer transition-all flex items-center gap-4 ${
                  selectedConversationId === conv.id 
                    ? 'bg-brand-teal text-white shadow-xl shadow-brand-teal/20 border-brand-teal' 
                    : 'bg-white text-brand-blue hover:border-brand-teal border-slate-100'
                }`}
              >
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl ${
                  selectedConversationId === conv.id ? 'bg-white/20' : 'bg-slate-50'
                }`}>
                  {conv.icon}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-center mb-1">
                    <h4 className="text-sm font-black truncate">{conv.name}</h4>
                    <span className={`text-[8px] font-black uppercase ${selectedConversationId === conv.id ? 'text-white/60' : 'text-slate-400'}`}>
                      {conv.time}
                    </span>
                  </div>
                  <p className={`text-[10px] font-bold truncate ${selectedConversationId === conv.id ? 'text-white/80' : 'text-slate-400'}`}>
                    {conv.lastMsg}
                  </p>
                </div>
              </div>
            ))}
          </div>
        );
      case 'TEAM':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Center Staffing</h2>
            {staff.map(s => (
              <div 
                key={s.id} 
                onClick={() => { setSelectedStaffId(s.id); setIsEditingStaff(false); }}
                className={`p-6 rounded-[40px] border cursor-pointer transition-all flex items-center justify-between shadow-sm ${
                  selectedStaffId === s.id 
                  ? 'bg-brand-blue text-white border-brand-blue shadow-lg' 
                  : 'bg-white text-brand-blue border-slate-100 hover:border-brand-teal'
                }`}
              >
                <div className="flex items-center gap-4">
                  <img src={s.avatarUrl} className="w-12 h-12 rounded-full border-2 border-white shadow-sm object-cover" />
                  <div>
                    <p className="text-sm font-black truncate">{s.name}</p>
                    <p className={`text-[10px] font-black uppercase tracking-widest ${selectedStaffId === s.id ? 'text-white/70' : 'text-brand-teal'}`}>
                      {s.role}
                    </p>
                  </div>
                </div>
                <span className={`text-[9px] font-black uppercase ${selectedStaffId === s.id ? 'text-green-300' : 'text-green-500'}`}>On Shift</span>
              </div>
            ))}
          </div>
        );
      case 'SCHEDULE':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">My Work Schedule</h2>
            {['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'].map(day => (
               <div key={day} className="p-6 bg-white border border-slate-100 rounded-[40px] flex justify-between items-center shadow-sm">
                 <span className="font-black text-slate-800">{day}</span>
                 <span className="text-[10px] font-black text-brand-teal bg-brand-teal/5 px-3 py-1 rounded-full">08:00 AM - 04:30 PM</span>
               </div>
            ))}
          </div>
        );
      case 'LESSON_PLANS':
        const lpTitle = currentUser?.role === UserRole.ADMIN ? 'Teacher Curriculums' : 'My Lesson Plans';
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">{lpTitle}</h2>
            {lessonPlans.map(lp => (
              <div 
                key={lp.id} 
                onClick={() => { setSelectedLessonPlanId(lp.id); setIsCreatingLesson(false); }}
                className={`p-6 rounded-[40px] border cursor-pointer transition-all ${selectedLessonPlanId === lp.id ? 'bg-brand-teal text-white shadow-xl shadow-brand-teal/20' : 'bg-white text-brand-blue hover:border-brand-teal'}`}
              >
                <h4 className="text-sm font-black mb-1">{lp.title}</h4>
                <p className={`text-[10px] font-bold uppercase opacity-60 ${selectedLessonPlanId === lp.id ? 'text-white' : 'text-slate-400'}`}>{lp.theme} • {lp.status}</p>
              </div>
            ))}
            {currentUser?.role === UserRole.TEACHER && (
              <button 
                onClick={() => { setIsCreatingLesson(true); setSelectedLessonPlanId(null); }}
                className="w-full py-4 bg-brand-yellow text-brand-blue font-black rounded-3xl mt-4 shadow-lg shadow-brand-yellow/10"
              >
                + Create New Lesson Plan
              </button>
            )}
          </div>
        );
      case 'MY_STUDENTS':
      case 'STUDENTS':
        const studentsTitle = currentUser?.role === UserRole.TEACHER ? 'Classroom Roster' : 'My Family';
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">{studentsTitle}</h2>
            {accessibleChildren.map(c => (
              <NestCard key={c.id} child={c} selected={selectedChildId === c.id} onClick={() => setSelectedChildId(c.id)} />
            ))}
          </div>
        );
      case 'BILLING':
        return (
          <div className="space-y-6 animate-in slide-in-from-left-8">
            <h2 className="text-2xl font-black text-brand-blue">Accounts</h2>
            {accessibleChildren.map(c => (
              <div key={c.id} className="p-6 bg-white border border-slate-100 rounded-[40px] shadow-sm flex justify-between items-center">
                 <p className="text-sm font-black text-brand-blue">{c.firstName}'s Family</p>
                 <span className="text-[9px] font-black text-brand-teal uppercase tracking-widest bg-brand-teal/5 px-3 py-1 rounded-full">Good Standing</span>
              </div>
            ))}
          </div>
        );
      default:
        return (
          <div className="space-y-5">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Live Activity Hub</h3>
            {accessibleChildren.map(c => (
              <NestCard key={c.id} child={c} selected={selectedChildId === c.id} onClick={() => setSelectedChildId(c.id)} />
            ))}
          </div>
        );
    }
  };

  const SidebarContent = () => {
    const role = currentUser?.role;

    const navItems = [
      { id: 'DAILY_OPS', label: 'Home Hub', icon: '🧭', roles: [UserRole.ADMIN, UserRole.TEACHER, UserRole.PARENT] },
      { id: 'MESSAGES', label: 'Messages', icon: '💬', roles: [UserRole.ADMIN, UserRole.TEACHER, UserRole.PARENT] },
      { id: 'BILLING', label: 'Billing', icon: '💰', roles: [UserRole.ADMIN, UserRole.PARENT] },
      { id: 'MY_STUDENTS', label: 'My Kids', icon: '🧸', roles: [UserRole.PARENT] },
      { id: 'STUDENTS', label: 'Students', icon: '🎒', roles: [UserRole.TEACHER] },
      { id: 'SCHEDULE', label: 'My Shift', icon: '⏰', roles: [UserRole.TEACHER] },
      { id: 'LESSON_PLANS', label: 'Curriculum', icon: '📖', roles: [UserRole.ADMIN, UserRole.TEACHER] },
      { id: 'ENROLLMENT', label: 'Enrollment', icon: '📝', roles: [UserRole.ADMIN] },
      { id: 'ANALYTICS', label: 'Analytics', icon: '📊', roles: [UserRole.ADMIN] },
      { id: 'TEAM', label: 'Staffing', icon: '👥', roles: [UserRole.ADMIN] },
      { id: 'INTEGRATIONS', label: 'Integrations', icon: '🔗', roles: [UserRole.ADMIN] },
      { id: 'SETTINGS', label: 'Settings', icon: '⚙️', roles: [UserRole.ADMIN] },
    ].filter(item => item.roles.includes(role!));

    return (
      <div className="space-y-12">
        <div className="space-y-1.5">
          <h3 className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] mb-6 pl-4">{role} PORTAL</h3>
          {navItems.map(item => (
            <button 
              key={item.id} 
              onClick={() => { 
                setActiveSection(item.id as AppSection); 
                setSelectedChildId(null); 
                setSelectedStaffId(null);
                setSelectedLessonPlanId(null); 
                setIsCreatingLesson(false); 
                setSelectedConversationId(null);
                setIsEditingStaff(false);
              }} 
              className={`w-full text-left px-5 py-4 rounded-2xl text-sm font-black transition-all ${activeSection === item.id ? 'bg-brand-teal text-white shadow-xl shadow-brand-teal/20' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <span className="mr-4 opacity-70">{item.icon}</span> {item.label}
            </button>
          ))}
        </div>
      </div>
    );
  };

  if (!isAuthenticated) return <LoginScreen onLogin={(role, email) => { setCurrentUser({ role, email }); setIsAuthenticated(true); setActiveSection('DAILY_OPS'); }} />;

  return (
    <>
      <AdminLayout
        sidebar={<SidebarContent />}
        listPanel={<ListPanelContent />}
        detailPanel={<DetailPanelContent />}
        onLogout={() => { setIsAuthenticated(false); setCurrentUser(null); setActiveSection('DAILY_OPS'); }}
        onGoHome={() => { 
          setActiveSection('DAILY_OPS'); 
          setSelectedChildId(null); 
          setSelectedStaffId(null);
          setSelectedLessonPlanId(null); 
          setIsCreatingLesson(false); 
          setSelectedConversationId(null);
          setIsEditingStaff(false);
        }}
        onCheckIn={currentUser?.role !== UserRole.PARENT ? handleCheckInAll : undefined}
        onQuickAdd={currentUser?.role !== UserRole.PARENT ? () => showToast("Quick Log Triggered!") : undefined}
      />
      {toast && (
        <div className={`fixed bottom-12 left-1/2 -translate-x-1/2 px-12 py-5 rounded-[32px] shadow-3xl font-black text-white z-[200] animate-in slide-in-from-bottom-12 ${toast.type === 'success' ? 'bg-brand-blue/95 backdrop-blur-md' : 'bg-red-500'}`}>
          {toast.message}
        </div>
      )}
    </>
  );
};

export default App;
